function getText(lang, key, vars) {
  const dict = TRANSLATIONS[lang] || {};
  let str = dict[key] ?? TRANSLATIONS.en[key] ?? TRANSLATIONS.ko[key] ?? key;
  if (vars) {
    Object.keys(vars).forEach((k) => {
      str = str.replace(`{${k}}`, vars[k]);
    });
  }
  return str;
}

// 아래 값들은 관리자가 "설정" 화면에서 조정할 수 있어요 (초기값은 기본값).
// const가 아니라 let인 이유: 앱이 켜져 있는 동안 관리자가 값을 바꾸면 즉시 반영되도록 하기 위해서예요.
let TOTAL_QUOTA = 12;
let MONTHLY_FEE = 120; // 자녀 1인당 월 고정 요금 (CAD, 세전)
let TAX_RATE = 0.05; // 세금 5%
let DELIVERY_WEEKDAYS = [1, 2, 4]; // 0=일 1=월 2=화 3=수 4=목 5=금 6=토 (기본: 월화목)

// 관리자가 설정을 바꾸면 이 함수로 위 값들을 갱신합니다. 호출 후 리렌더를 트리거해야 화면에 반영돼요.
function applySettings({ monthlyFee, taxRate, totalQuota, deliveryWeekdays } = {}) {
  if (monthlyFee != null) MONTHLY_FEE = monthlyFee;
  if (taxRate != null) TAX_RATE = taxRate;
  if (totalQuota != null) TOTAL_QUOTA = totalQuota;
  if (deliveryWeekdays != null) DELIVERY_WEEKDAYS = deliveryWeekdays;
}

// 자녀별로 관리자가 개별 사이클 횟수(total_quota)를 지정했으면 그 값을, 아니면 전체 기본값(TOTAL_QUOTA)을 씁니다.
// (예: 여름방학 후 복귀하는 아이는 12가 아니라 남은 횟수만 관리자가 개별로 설정할 수 있어요.)
function getChildQuota(child) {
  return child?.total_quota || TOTAL_QUOTA;
}

// 자녀 수에 따라 요금이 올라가는 구조: 자녀 1인당 월 고정요금 + 세금
function calcFee(childrenCount) {
  const n = Math.max(1, childrenCount || 1);
  const subtotal = MONTHLY_FEE * n;
  const tax = subtotal * TAX_RATE;
  return { subtotal, tax, total: subtotal + tax, count: n };
}

function formatCAD(n) {
  return `$${n.toFixed(2)}`;
}

// 과일 이름 글자를 보고 그에 맞는 이모지를 골라줘요. 목록에 없는 과일이면 기본 과일 이모지를 보여줘요.
function getFruitEmoji(fruitName) {
  if (!fruitName) return "";
  const name = fruitName.toLowerCase();
  const table = [
    [["사과"], "🍎"],
    [["배"], "🍐"],
    [["바나나"], "🍌"],
    [["포도"], "🍇"],
    [["딸기"], "🍓"],
    [["귤", "감귤", "오렌지", "만다린", "한라봉", "천혜향", "레드향"], "🍊"],
    [["수박"], "🍉"],
    [["참외", "멜론"], "🍈"],
    [["복숭아", "천도"], "🍑"],
    [["키위"], "🥝"],
    [["파인애플"], "🍍"],
    [["토마토"], "🍅"],
    [["체리"], "🍒"],
    [["망고"], "🥭"],
    [["레몬"], "🍋"],
    [["코코넛"], "🥥"],
    [["블루베리"], "🫐"],
    [["자두"], "🍑"],
    [["석류"], "🍎"],
    [["감", "홍시", "곶감"], "🍊"],
    [["무화과"], "🍇"],
    [["용과", "드래곤"], "🍈"],
  ];
  for (const [keywords, emoji] of table) {
    if (keywords.some((k) => name.includes(k))) return emoji;
  }
  return "🍏"; // 목록에 없는 과일이면(예: 새로 추가한 과일) 기본 과일 이모지를 보여줘요.
}

// ---- 밴쿠버(태평양) 표준시간대 기준 날짜 계산 ----
function vancouverNow() {
  const now = new Date();
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Vancouver",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(now);
  const get = (t) => Number(parts.find((p) => p.type === t).value);
  return new Date(get("year"), get("month") - 1, get("day"), get("hour") % 24, get("minute"), get("second"));
}

function monthKey(year, month) {
  return `${year}-${String(month).padStart(2, "0")}`;
}

// 앱을 껐다 켜지 않고도 최신 버전을 강제로 받아오는 새로고침이에요.
// 서비스워커에게 업데이트를 확인시키고, 브라우저 캐시를 우회하도록 주소에 타임스탬프를 붙여 다시 불러와요.
async function forceAppRefresh() {
  try {
    if ("serviceWorker" in navigator) {
      const regs = await navigator.serviceWorker.getRegistrations();
      await Promise.all(regs.map((reg) => reg.update()));
    }
  } catch (e) {
    // 업데이트 확인이 실패해도 새로고침 자체는 계속 진행해요.
  }
  const url = new URL(window.location.href);
  url.searchParams.set("_r", Date.now().toString());
  window.location.href = url.toString();
}

// 현재(밴쿠버 기준) 활성 월 — 캘린더가 자동으로 이 달을 보여줌
function getActiveYearMonth() {
  const now = vancouverNow();
  return { year: now.getFullYear(), month: now.getMonth() + 1 };
}

function monthLabel(year, month) {
  return `${year}년 ${month}월`;
}

// 학부모 화면(신청 탭, 메뉴판 탭)에서 언어 설정에 맞게 "년/월" 표기를 바꿔줘요.
// 관리자 화면은 계속 monthLabel()(한국어 고정)을 그대로 써요.
function monthLabelLocalized(year, month, language) {
  const localeMap = { ko: "ko-KR", en: "en-US", fr: "fr-FR", zh: "zh-CN" };
  const locale = localeMap[language] || "ko-KR";
  try {
    return new Intl.DateTimeFormat(locale, { year: "numeric", month: "long" }).format(new Date(year, month - 1, 1));
  } catch (e) {
    return monthLabel(year, month);
  }
}

// 상세 팝업 헤더에 쓰는 "월 일" 표기 — 언어마다 순서가 달라서(예: 영어 Aug 15, 프랑스어 15 août) Intl로 맞춰요.
function monthDayLabelLocalized(year, month, day, language) {
  const localeMap = { ko: "ko-KR", en: "en-US", fr: "fr-FR", zh: "zh-CN" };
  const locale = localeMap[language] || "ko-KR";
  try {
    return new Intl.DateTimeFormat(locale, { month: "long", day: "numeric" }).format(new Date(year, month - 1, day));
  } catch (e) {
    return `${month}월 ${day}일`;
  }
}

