// 평일만 도시락 제공 대상 날짜로 취급
function getWeekday(year, month, day) {
  return new Date(year, month - 1, day).getDay();
}

function daysInMonth(year, month) {
  return new Date(year, month, 0).getDate();
}

function firstWeekdayOfMonth(year, month) {
  return new Date(year, month - 1, 1).getDay();
}

// 신청/스킵 변경 마감: 배송 주간의 전주 금요일 23:59까지 (밴쿠버 시간 기준)
function getSkipDeadline(year, month, day) {
  const date = new Date(year, month - 1, day);
  const dow = date.getDay(); // 월=1, 화=2, 목=4
  const offsetFromMonday = dow - 1;
  const monday = new Date(year, month - 1, day - offsetFromMonday);
  const deadline = new Date(monday);
  deadline.setDate(deadline.getDate() - 3); // 전주 금요일
  deadline.setHours(23, 59, 59, 999);
  return deadline;
}

function isSkipLocked(year, month, day) {
  return vancouverNow() > getSkipDeadline(year, month, day);
}

// 아직 마감 전인 신청일 중, 가장 가까운 마감이 지금부터 withinHours 시간 이내면 그 마감 시각을 돌려줘요.
// (마감 임박 리마인더 배너를 띄우는 데 써요)
function getUpcomingDeadline(availableDays, year, month, withinHours) {
  const now = vancouverNow();
  let nearest = null;
  for (const day of availableDays) {
    const deadline = getSkipDeadline(year, month, day);
    if (deadline > now && (!nearest || deadline < nearest)) nearest = deadline;
  }
  if (nearest && nearest - now <= withinHours * 3600 * 1000) return nearest;
  return null;
}

