// 관리자 활동 로그 — 평소엔 최근 5개만 접어서 보여주고, 필요하면 펼쳐볼 수 있어요. 쌓인 로그는 한 번에 정리할 수도 있어요.
// 매주 자동으로 쌓이는 백업 목록을 보여주고, 원하는 시점 걸 골라 다운로드할 수 있게 해줘요.
function BackupsListPanel() {
  const [backups, setBackups] = useState(null); // null = 아직 안 불러옴
  const [loading, setLoading] = useState(false);
  const [downloadingId, setDownloadingId] = useState(null);

  const load = () => {
    setLoading(true);
    api
      .getBackupsList()
      .then(setBackups)
      .catch(() => setBackups([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleDownload = async (id, createdAt) => {
    setDownloadingId(id);
    try {
      const backup = await api.getBackupData(id);
      const json = JSON.stringify(backup.data, null, 2);
      const blob = new Blob([json], { type: "application/json;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      const dateLabel = new Date(createdAt).toISOString().slice(0, 10);
      link.download = `meallions-backup-${dateLabel}.json`;
      link.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      // 조용히 무시 — 버튼이 눌린 상태로 안 남게만 처리해요.
    }
    setDownloadingId(null);
  };

  return (
    <div style={styles.profileCard}>
      {backups === null || loading ? (
        <div style={{ fontSize: 13, color: "#9AA39A", padding: "10px 2px" }}>불러오는 중...</div>
      ) : backups.length === 0 ? (
        <div style={{ fontSize: 13, color: "#9AA39A", padding: "10px 2px" }}>
          아직 자동 백업이 없어요. 매주 한 번씩 자동으로 쌓일 거예요.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {backups.map((b) => (
            <div key={b.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", ...styles.adminRow, padding: "10px 12px" }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: "#33402F" }}>
                {new Date(b.created_at).toLocaleDateString("ko-KR", { year: "numeric", month: "long", day: "numeric" })}
              </div>
              <button
                onClick={() => handleDownload(b.id, b.created_at)}
                disabled={downloadingId === b.id}
                style={{ ...styles.revokeBtn, width: "auto", padding: "8px 14px", marginTop: 0 }}
              >
                {downloadingId === b.id ? "받는 중..." : "다운로드"}
              </button>
            </div>
          ))}
        </div>
      )}
      <button onClick={load} disabled={loading} style={{ ...styles.revokeBtn, width: "100%", marginTop: 10 }}>
        {loading ? "새로고침 중..." : "새로고침"}
      </button>
    </div>
  );
}

function ActivityLogPanel({ activityLog, onClearActivityLog }) {
  const [expanded, setExpanded] = useState(false);
  const [clearArmed, setClearArmed] = useState(false);
  const [clearing, setClearing] = useState(false);
  const visibleLogs = expanded ? activityLog : activityLog.slice(0, 5);

  const handleClearClick = async () => {
    if (!clearArmed) {
      setClearArmed(true);
      setTimeout(() => setClearArmed(false), 4000);
      return;
    }
    setClearing(true);
    try {
      await onClearActivityLog();
    } catch (e) {
      // 에러 배너는 상위에서 이미 보여줘요.
    }
    setClearing(false);
    setClearArmed(false);
  };

  return (
    <div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        {activityLog.length === 0 && (
          <div style={{ fontSize: 13, color: "#9AA39A", padding: "10px 2px" }}>아직 기록된 활동이 없어요.</div>
        )}
        {visibleLogs.map((log) => (
          <div key={log.id} style={{ ...styles.adminRow, padding: "10px 12px" }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: "#33402F" }}>{log.target_description}</div>
            <div style={{ fontSize: 11.5, color: "#9AA39A", marginTop: 2 }}>
              {log.admin_name || "관리자"} · {new Date(log.created_at).toLocaleString("ko-KR", { timeZone: "America/Vancouver" })}
            </div>
          </div>
        ))}
      </div>

      {activityLog.length > 5 && (
        <button onClick={() => setExpanded((v) => !v)} style={{ ...styles.revokeBtn, width: "100%", marginTop: 8 }}>
          {expanded ? "접기" : `전체 보기 (${activityLog.length}개)`}
        </button>
      )}

      {activityLog.length > 0 && (
        <button
          onClick={handleClearClick}
          disabled={clearing}
          style={{
            ...styles.revokeBtn,
            width: "100%",
            marginTop: 8,
            color: clearArmed ? "#fff" : undefined,
            background: clearArmed ? "#C0392B" : undefined,
          }}
        >
          {clearing ? "정리 중..." : clearArmed ? "정말로 로그를 전부 지울까요? 다시 눌러 확정" : "오래된 로그 정리 (전체 삭제)"}
        </button>
      )}
    </div>
  );
}

// 결제일과 별개로 "실제 서비스 시작일"을 관리자가 지정할 수 있는 작은 위젯이에요.
// 예: 7/1에 결제했지만 학부모가 7/14부터 이용을 원하면, 그 이전 신청 건은 사이클에서 빠져요.
function ServiceStartDateField({ child, onUpdateServiceStartDate }) {
  const [date, setDate] = useState(child.service_start_date || "");
  const [saved, setSaved] = useState(false);

  const handleSave = () => {
    onUpdateServiceStartDate(child.id, date || null);
    setSaved(true);
    setTimeout(() => setSaved(false), 1500);
  };

  return (
    <div style={{ marginTop: 10 }}>
      <div style={{ fontSize: 11.5, color: "#9AA39A", marginBottom: 4 }}>서비스 시작일</div>
      <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} style={{ ...styles.fieldInput, marginBottom: 0, flex: 1, minWidth: 0, WebkitAppearance: "none", appearance: "none" }} />
        <button onClick={handleSave} style={{ ...styles.revokeBtn, width: "auto", padding: "10px 16px", flexShrink: 0, marginTop: 0 }}>
          {saved ? "저장됨 ✓" : "저장"}
        </button>
      </div>
    </div>
  );
}

// 이 자녀만 사이클 횟수(기본 12회)를 다르게 지정하는 위젯이에요.
// 예: 여름방학 끝나고 복귀하는 아이는 남은 횟수만큼만 채워서 다음 결제가 그때 뜨도록 할 수 있어요.
// 비워두면(빈 칸으로 저장) 다시 전체 기본값(관리자 설정의 사이클 요금 횟수)을 따릅니다.
function TotalQuotaField({ child, onUpdateTotalQuota }) {
  const [value, setValue] = useState(child.total_quota != null ? String(child.total_quota) : "");
  const [status, setStatus] = useState("idle"); // idle | saving | saved | error

  const handleSave = async () => {
    const parsed = value.trim() === "" ? null : Math.max(1, parseInt(value, 10) || 1);
    setStatus("saving");
    try {
      await onUpdateTotalQuota(child.id, parsed);
      setStatus("saved");
      setTimeout(() => setStatus("idle"), 1500);
    } catch (e) {
      setStatus("error");
      setTimeout(() => setStatus("idle"), 2500);
    }
  };

  return (
    <div style={{ marginTop: 10 }}>
      <div style={{ fontSize: 11.5, color: "#9AA39A", marginBottom: 4 }}>
        이 자녀만 사이클 횟수 (비워두면 기본 {TOTAL_QUOTA}회)
      </div>
      <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
        <input
          type="number"
          min="1"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          placeholder={String(TOTAL_QUOTA)}
          style={{ ...styles.fieldInput, marginBottom: 0, flex: 1, minWidth: 0 }}
        />
        <button onClick={handleSave} disabled={status === "saving"} style={{ ...styles.revokeBtn, width: "auto", padding: "10px 16px", flexShrink: 0, marginTop: 0 }}>
          {status === "saving" ? "저장 중..." : status === "saved" ? "저장됨 ✓" : status === "error" ? "저장 실패 ✕" : "저장"}
        </button>
      </div>
      {status === "error" && (
        <div style={{ fontSize: 11, color: "#C0392B", marginTop: 4 }}>저장 중 오류가 발생했어요. 다시 시도해주세요.</div>
      )}
    </div>
  );
}

// 학부모 가정 전체의 이번 달·다음 달 신청 내역(달력 체크)을 통째로 지워서 처음부터 다시 신청받는 버튼이에요.
// 신청은 자녀별이 아니라 가정 전체가 공유하는 값이라, 이 버튼은 자녀 카드마다 보이지만 항상 그 가정 전체에 적용돼요.
// 되돌릴 수 없는 동작이라 실수로 누르지 않도록 두 번 눌러야 확정되게 만들었어요.
function ResetOrdersButton({ profileId, parentName, onResetOrders }) {
  const [armed, setArmed] = useState(false);
  const [status, setStatus] = useState("idle"); // idle | working | done | error

  const handleClick = async () => {
    if (!armed) {
      setArmed(true);
      setTimeout(() => setArmed(false), 4000); // 4초 안에 다시 안 누르면 확인 취소
      return;
    }
    setStatus("working");
    try {
      await onResetOrders(profileId, parentName);
      setStatus("done");
      setArmed(false);
      setTimeout(() => setStatus("idle"), 1800);
    } catch (e) {
      setStatus("error");
      setArmed(false);
      setTimeout(() => setStatus("idle"), 2500);
    }
  };

  return (
    <div style={{ marginTop: 10 }}>
      <button
        onClick={handleClick}
        disabled={status === "working"}
        style={{ ...styles.revokeBtn, width: "100%", color: armed ? "#fff" : undefined, background: armed ? "#C0392B" : undefined }}
      >
        {status === "working"
          ? "초기화 중..."
          : status === "done"
          ? "초기화됨 ✓"
          : status === "error"
          ? "초기화 실패 ✕"
          : armed
          ? `정말로 ${parentName} 가정 신청을 전부 지울까요? 다시 눌러 확정`
          : `${parentName} 가정 신청 내역 초기화 (다시 신청받기)`}
      </button>
    </div>
  );
}


function MiniBarChart({ data, valueKey, labelKey, color, formatValue }) {
  const max = Math.max(1, ...data.map((d) => d[valueKey]));
  const barWidth = 32;
  const gap = 14;
  const chartHeight = 110;
  const width = data.length * (barWidth + gap) + gap;

  return (
    <div style={{ ...styles.profileCard, overflowX: "auto" }}>
      <svg width={width} height={chartHeight + 34} style={{ display: "block", minWidth: "100%" }}>
        {data.map((d, i) => {
          const value = d[valueKey] || 0;
          const barHeight = Math.max(2, (value / max) * chartHeight);
          const x = gap + i * (barWidth + gap);
          const y = chartHeight - barHeight;
          const label = (d[labelKey] || "").slice(5); // "2026-07" -> "07"
          return (
            <g key={i}>
              <text x={x + barWidth / 2} y={y - 6} textAnchor="middle" fontSize="10" fill="#5C6A5C" fontWeight="700">
                {formatValue(value)}
              </text>
              <rect x={x} y={y} width={barWidth} height={barHeight} rx="6" fill={color} />
              <text x={x + barWidth / 2} y={chartHeight + 18} textAnchor="middle" fontSize="11" fill="#9AA39A">
                {label}월
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

function AdminApp({ accounts, removedChildPayments, menusByMonth, onUpdateMenus, onDeleteMenuMonth, notices, onUpdateNotices, onSendNoticeNotification, onSendMenuNotification, etransferInfo, onUpdateEtransferInfo, onApprovePayment, onRevokePayment, promoCodes, onCreatePromoCode, onTogglePromoCode, onDeletePromoCode, onUpdateServiceStartDate, onUpdateTotalQuota, onResetOrders, pricing, onUpdatePricing, deliveryWeekdays, onUpdateDeliveryWeekdays, allProfilesForRole, onUpdateProfileRole, onExportFullBackup, monthlyStats, activityLog, onClearActivityLog, activeYear, activeMonth, activeKey, onLogout, dataError, onDismissDataError, language, setLanguage, t }) {
  const [tab, setTab] = useState("overview");
  const [overviewView, setOverviewView] = useState("calendar"); // calendar | daily | family — 신청 현황 보기 방식
  const [paymentFilter, setPaymentFilter] = useState("all"); // all | partial (일부만 결제한 가정)
  const [sortBy, setSortBy] = useState("name"); // name | orders | unpaid
  const activeLabel = monthLabel(activeYear, activeMonth);
  const getOrder = (a) => a.order || [];
  const totalFamilyVisits = accounts.reduce((sum, a) => sum + getOrder(a).length, 0);
  const totalBoxes = accounts.reduce((sum, a) => sum + getOrder(a).length * (a.children.length || 1), 0);

  // 날짜별 신청 현황 — 이번 달 배송일마다 몇 가정/몇 개 도시락이 필요한지, 누가 신청했는지 정리해요.
  const menusThisMonth = menusByMonth[activeKey] || {};
  const dailyBreakdown = Object.keys(menusThisMonth)
    .map(Number)
    .sort((a, b) => a - b)
    .map((day) => {
      const dateStr = `${activeYear}-${String(activeMonth).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      // 가정 내 자녀 중 서비스 시작이 가장 늦은 자녀 기준으로, 그 날짜 이전이면 이 가정은 아직
      // 신청 대상이 아니었던 걸로 보고 스킵/신청 집계 자체에서 빼요.
      const eligibleAccounts = accounts.filter((a) => {
        const familyStart = a.children.reduce((latest, c) => {
          if (!c.service_start_date) return latest;
          return !latest || c.service_start_date > latest ? c.service_start_date : latest;
        }, null);
        return !familyStart || dateStr >= familyStart;
      });
      const families = eligibleAccounts
        .filter((a) => getOrder(a).includes(day))
        .map((a) => ({ parentName: a.parentName, childrenNames: a.children.map((c) => c.name) }));
      const totalBoxesForDay = families.reduce((sum, f) => sum + f.childrenNames.length, 0);
      const skippedFamilies = eligibleAccounts
        .filter((a) => !getOrder(a).includes(day))
        .map((a) => ({ parentName: a.parentName, childrenNames: a.children.map((c) => c.name) }));
      const totalSkippedBoxesForDay = skippedFamilies.reduce((sum, f) => sum + f.childrenNames.length, 0);
      const dayMenu = menusThisMonth[day];
      return {
        day,
        weekday: getWeekday(activeYear, activeMonth, day),
        families,
        totalBoxesForDay,
        skippedFamilies,
        totalSkippedBoxesForDay,
        isHoliday: !!dayMenu?.isHoliday,
        holidayLabel: dayMenu?.holidayLabel,
      };
    });

  // 캘린더(달력)형 뷰 — 메뉴판처럼 한 주씩 월·화·목을 가로로 묶어서 한눈에 볼 수 있게 해요.
  const calendarFirstWd = firstWeekdayOfMonth(activeYear, activeMonth);
  const calendarWeekGroups = {};
  dailyBreakdown.forEach((d) => {
    const weekIndex = Math.floor((d.day - 1 + calendarFirstWd) / 7);
    if (!calendarWeekGroups[weekIndex]) calendarWeekGroups[weekIndex] = {};
    calendarWeekGroups[weekIndex][d.weekday] = d;
  });
  const calendarWeekIndexes = Object.keys(calendarWeekGroups).map(Number).sort((a, b) => a - b);

  // 학부모 목록 정렬 — 이름순 / 신청 많은순 / 미결제 자녀 있는 가정 우선
  const sortedAccounts = [...accounts].sort((a, b) => {
    if (sortBy === "orders") return getOrder(b).length - getOrder(a).length;
    if (sortBy === "unpaid") {
      const aUnpaid = a.children.some((c) => (c.payment?.status || "unpaid") === "unpaid") ? 1 : 0;
      const bUnpaid = b.children.some((c) => (c.payment?.status || "unpaid") === "unpaid") ? 1 : 0;
      return bUnpaid - aUnpaid;
    }
    return (a.parentName || "").localeCompare(b.parentName || "", "ko");
  });

  // 결제는 이제 자녀 1명 단위입니다 — 모든 가정의 모든 자녀를 한 목록으로 펼쳐서 계산해요.
  const allChildPayments = accounts.flatMap((a) =>
    a.children.map((c) => ({ parent: a, child: c, status: c.payment?.status || "unpaid", amount: c.payment?.amount || calcFee(1).total }))
  );
  const totalRevenue = allChildPayments.reduce((sum, p) => sum + calcFee(1).total, 0);
  const allergyKids = accounts.flatMap((a) =>
    a.children.filter((c) => c.allergy && c.allergy !== "없음").map((c) => ({ parent: a, child: c }))
  );
  const paidPayments = allChildPayments.filter((p) => p.status === "paid");
  const pendingPayments = allChildPayments.filter((p) => p.status === "pending");
  const unpaidPayments = allChildPayments.filter((p) => p.status === "unpaid");
  const totalCollected = paidPayments.reduce((sum, p) => sum + p.amount, 0);

  // 다자녀 중 일부만 결제한(미납 자녀와 결제완료/대기 자녀가 섞인) 가정만 걸러보기
  const partialFamilyIds = new Set(
    accounts
      .filter((a) => a.children.length > 1)
      .filter((a) => {
        const statuses = new Set(a.children.map((c) => c.payment?.status || "unpaid"));
        return statuses.size > 1;
      })
      .map((a) => a.id)
  );
  const visiblePayments = paymentFilter === "partial" ? allChildPayments.filter((p) => partialFamilyIds.has(p.parent.id)) : allChildPayments;

  // CSV(엑셀에서 열 수 있는 형식) 내보내기 — 학부모/자녀/신청현황/결제상태를 한 줄씩
  const formatDateForCsv = (d) => (d ? new Date(d).toLocaleString("ko-CA", { timeZone: "America/Vancouver" }) : "");

  const handleExportCsv = () => {
    const header = [
      "학부모", "전화번호", "주소", "자녀 이름", "자녀 나이", "알러지",
      "이번달 신청 날짜", "이번달 신청 횟수",
      "사이클 진행률(사용/총)", "남은 횟수",
      "결제상태", "결제금액", "결제 제출일", "결제 승인일",
      "프로모코드", "할인금액",
    ];
    const rows = accounts.flatMap((a) =>
      a.children.map((c) => {
        const childQuota = getChildQuota(c);
        const cycleUsed = c.cycleUsed || 0;
        const remaining = Math.max(0, childQuota - cycleUsed);
        const orderDays = (getOrder(a) || []).slice().sort((x, y) => x - y);
        return [
          a.parentName || "",
          a.phone || "",
          a.address || "",
          c.name || "",
          c.age || "",
          c.allergy || "",
          orderDays.join(", "),
          String(orderDays.length),
          `${cycleUsed}/${childQuota}`,
          String(remaining),
          c.payment?.status === "paid" ? "결제완료" : c.payment?.status === "pending" ? "입금확인중" : "미결제",
          String(c.payment?.amount || calcFee(1).total),
          formatDateForCsv(c.payment?.submitted_at),
          formatDateForCsv(c.payment?.paid_at),
          c.payment?.promo_code || "",
          c.payment?.discount_amount ? String(c.payment.discount_amount) : "",
        ];
      })
    );
    const escapeCsv = (v) => `"${String(v).replace(/"/g, '""')}"`;
    const csv = [header, ...rows].map((row) => row.map(escapeCsv).join(",")).join("\r\n");
    const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" }); // BOM 포함 — 엑셀에서 한글 안 깨지도록
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `meallions-${activeKey}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div style={styles.app}>
      <style>{`
        * { box-sizing: border-box; }
        body { margin: 0; }
        @keyframes riseIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
        .fade-item { animation: riseIn 0.25s ease both; }
      `}</style>

      <header style={{ ...styles.header, borderBottom: "3px solid #8A7355" }}>
        <div style={styles.headerTop}>
          <img src={LOGO_SRC} alt="MEALLIONS" style={styles.logoImgHeader} />
          <div style={{ flex: 1 }}>
            <div style={styles.brandSub}>
              <span style={styles.adminBadge}>관리자</span>
            </div>
          </div>
          <LanguageSelect language={language} setLanguage={setLanguage} t={t} compact />
          <button onClick={forceAppRefresh} style={styles.logoutBtn} title="새로고침">
            <RefreshCw size={16} color="#4F7A44" />
          </button>
          <button onClick={onLogout} style={styles.logoutBtn}>
            <LogOut size={16} color="#8A7355" />
          </button>
        </div>
      </header>

      {dataError && (
        <div style={styles.dataErrorBanner}>
          <span>{dataError}</span>
          <button onClick={onDismissDataError} style={styles.paymentNoticeClose}>
            <X size={16} />
          </button>
        </div>
      )}

      <main style={styles.main}>
        {tab === "overview" && (
          <div>
            <div style={styles.adminStatRow}>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>전체 학부모</div>
                <div style={styles.adminStatValue}>{accounts.length}명</div>
              </div>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>신청 가구 수</div>
                <div style={styles.adminStatValue}>{totalFamilyVisits}회</div>
              </div>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>총 도시락 개수</div>
                <div style={styles.adminStatValue}>{totalBoxes}개</div>
              </div>
            </div>
            <p style={{ ...styles.helperText, marginTop: 8 }}>
              {activeLabel} 기준 · 도시락 개수는 가구별 신청 횟수 × 자녀 수로 계산돼요 (그로서리 준비량 참고용).
            </p>

            <div style={styles.adminStatRow}>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>예상 매출</div>
                <div style={styles.adminStatValue}>{formatCAD(totalRevenue)}</div>
              </div>
            </div>

            {monthlyStats.length > 1 && (
              <>
                <div style={{ ...styles.sectionTitle, marginTop: 18 }}>최근 매출 추이</div>
                <MiniBarChart
                  data={monthlyStats}
                  valueKey="revenue"
                  labelKey="yearMonth"
                  color="#4F7A44"
                  formatValue={(v) => formatCAD(v)}
                />
                <div style={{ ...styles.sectionTitle, marginTop: 18 }}>최근 신청 추이</div>
                <MiniBarChart
                  data={monthlyStats}
                  valueKey="orders"
                  labelKey="yearMonth"
                  color="#3E6BC7"
                  formatValue={(v) => `${v}회`}
                />
              </>
            )}

            {allergyKids.length > 0 && (
              <div style={styles.allergyBanner}>
                ⚠️ 알러지 주의 원아 {allergyKids.length}명: {allergyKids.map(({ child }) => `${child.name}(${child.allergy})`).join(", ")}
              </div>
            )}

            <div style={{ ...styles.sectionTitle, marginTop: 18, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
              <span>신청 현황</span>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                <button
                  onClick={() => setOverviewView("calendar")}
                  style={{ ...styles.filterChip, ...(overviewView === "calendar" ? styles.filterChipActive : {}) }}
                >
                  달력형
                </button>
                <button
                  onClick={() => setOverviewView("daily")}
                  style={{ ...styles.filterChip, ...(overviewView === "daily" ? styles.filterChipActive : {}) }}
                >
                  날짜별
                </button>
                <button
                  onClick={() => setOverviewView("family")}
                  style={{ ...styles.filterChip, ...(overviewView === "family" ? styles.filterChipActive : {}) }}
                >
                  가족별
                </button>
              </div>
            </div>

            {overviewView === "calendar" ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                {calendarWeekIndexes.length === 0 && (
                  <div style={{ fontSize: 13, color: "#9AA39A", padding: "10px 2px" }}>이번 달 등록된 배송일이 없어요.</div>
                )}
                {calendarWeekIndexes.map((wi, rowIdx) => (
                  <div key={wi}>
                    <div style={styles.menuBoardWeekLabel}>{rowIdx + 1}주차</div>
                    <div style={styles.menuBoardWeekRow}>
                      {DELIVERY_WEEKDAYS.map((wd) => {
                        const d = calendarWeekGroups[wi][wd];
                        return (
                          <div key={wd} style={styles.calendarDayCol}>
                            <div style={styles.menuBoardDayHeader}>
                              <span style={{ fontSize: 11, color: "#9AA39A" }}>{WEEKDAYS[wd]}</span>
                              {d && <span style={{ fontSize: 15, fontWeight: 800, color: "#33402F", marginLeft: 4 }}>{d.day}</span>}
                            </div>
                            {d && d.isHoliday ? (
                              <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", marginTop: 6, textAlign: "center", fontSize: 11.5, fontWeight: 700, color: "#D9756B", lineHeight: 1.4 }}>
                                🇨🇦 {d.holidayLabel}
                              </div>
                            ) : d ? (
                              <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "center", marginTop: 6, textAlign: "center" }}>
                                <div style={{ fontSize: 16, fontWeight: 800, color: d.families.length > 0 ? "#4F7A44" : "#C9CFC9" }}>
                                  {d.families.length}
                                </div>
                                <div style={{ fontSize: 10, color: "#9AA39A" }}>가정 · {d.totalBoxesForDay}개</div>
                                <div style={{ height: 1, background: "#F2F6F2", margin: "6px 0" }} />
                                <div style={{ fontSize: 12.5, fontWeight: 700, color: "#C0392B" }}>{d.skippedFamilies.length}</div>
                                <div style={{ fontSize: 9.5, color: "#C9A9A5" }}>스킵 · {d.totalSkippedBoxesForDay}개</div>
                              </div>
                            ) : (
                              <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11.5, color: "#C9CFC9", textAlign: "center" }}>—</div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            ) : overviewView === "daily" ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {dailyBreakdown.length === 0 && (
                  <div style={{ fontSize: 13, color: "#9AA39A", padding: "10px 2px" }}>이번 달 등록된 배송일이 없어요.</div>
                )}
                {dailyBreakdown.map(({ day, weekday, families, totalBoxesForDay, skippedFamilies, totalSkippedBoxesForDay, isHoliday, holidayLabel }) => (
                  <div key={day} style={styles.dailyCard} className="fade-item">
                    <div style={styles.dailyCardHeader}>
                      <div style={styles.dailyDateBadge}>
                        <div style={{ fontSize: 10.5, color: "#9AA39A" }}>{WEEKDAYS[weekday]}</div>
                        <div style={{ fontSize: 19, fontWeight: 800, color: isHoliday ? "#D9756B" : "#33402F" }}>{day}</div>
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontSize: 13, color: "#7C8A7C" }}>
                          {activeMonth}월 {day}일 {isHoliday ? `· 🇨🇦 ${holidayLabel}` : "배송"}
                        </div>
                      </div>
                      {!isHoliday && (
                        <div style={{ display: "flex", flexDirection: "column", gap: 4, alignItems: "flex-end" }}>
                          <div style={styles.dailyCountBadge}>신청 {families.length}가정 · {totalBoxesForDay}개</div>
                          <div style={styles.dailySkipBadge}>스킵 {skippedFamilies.length}가정 · {totalSkippedBoxesForDay}개</div>
                        </div>
                      )}
                    </div>
                    {!isHoliday && (
                      <>
                        <div style={{ fontSize: 11, fontWeight: 700, color: "#4F7A44", marginTop: 10 }}>신청한 가정</div>
                        {families.length > 0 ? (
                          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 6 }}>
                            {families.map((f, i) => (
                              <div key={i} style={styles.familyPill}>
                                <span style={{ fontWeight: 700 }}>{f.parentName}</span>
                                <span style={{ color: "#9AA39A" }}> · {f.childrenNames.join(", ")}</span>
                              </div>
                            ))}
                          </div>
                        ) : (
                          <div style={{ fontSize: 12, color: "#C9CFC9", marginTop: 6 }}>신청한 가정이 없어요.</div>
                        )}

                        {skippedFamilies.length > 0 && (
                          <>
                            <div style={{ fontSize: 11, fontWeight: 700, color: "#B5872E", marginTop: 10 }}>스킵한 가정</div>
                            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 6 }}>
                              {skippedFamilies.map((f, i) => (
                                <div key={i} style={styles.familySkipPill}>
                                  <span style={{ fontWeight: 700 }}>{f.parentName}</span>
                                  <span style={{ color: "#C9A9A5" }}> · {f.childrenNames.join(", ")}</span>
                                </div>
                              ))}
                            </div>
                          </>
                        )}
                      </>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <>
                <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap", marginBottom: 12 }}>
                  <select value={sortBy} onChange={(e) => setSortBy(e.target.value)} style={styles.sortSelect}>
                    <option value="name">이름순</option>
                    <option value="orders">신청 많은순</option>
                    <option value="unpaid">미결제 우선</option>
                  </select>
                  <button onClick={handleExportCsv} style={styles.exportBtn}>CSV 내보내기</button>
                </div>
                <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                  {sortedAccounts.map((a) => (
                    <div key={a.id} style={styles.adminRow} className="fade-item">
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                        <div>
                          <div style={{ fontSize: 14.5, fontWeight: 800, color: "#33402F" }}>{a.parentName}</div>
                          <div style={{ fontSize: 12, color: "#9AA39A", marginTop: 2 }}>ID {a.id}{a.phone ? ` · ${a.phone}` : ""}</div>
                          {a.address && <div style={{ fontSize: 12, color: "#9AA39A", marginTop: 2 }}>📍 {a.address}</div>}
                        </div>
                        <div style={{ textAlign: "right" }}>
                          <div style={{ fontSize: 15, fontWeight: 800, color: "#4F7A44" }}>{getOrder(a).length}회 · {getOrder(a).length * (a.children.length || 1)}개</div>
                          <div style={{ fontSize: 11.5, color: "#9AA39A" }}>{formatCAD(calcFee(1).total)}/자녀 (고정)</div>
                        </div>
                      </div>
                      <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 10 }}>
                        {a.children.map((c) => {
                          const status = c.payment?.status || "unpaid";
                          return (
                            <div key={c.id} style={styles.childInfoRow}>
                              <div style={{ minWidth: 0 }}>
                                <span style={{ fontWeight: 700, fontSize: 13, color: "#33402F" }}>{c.name}</span>
                                <span style={{ fontSize: 11.5, color: "#9AA39A" }}> ({c.gender}·{c.age}세)</span>
                                <div style={{ fontSize: 11.5, color: c.allergy && c.allergy !== "없음" ? "#B5872E" : "#9AA39A", marginTop: 1 }}>
                                  알러지: {c.allergy || "미입력"}
                                </div>
                              </div>
                              <div
                                style={{
                                  ...styles.paymentBadge,
                                  flexShrink: 0,
                                  ...(status === "paid"
                                    ? styles.paymentBadgePaid
                                    : status === "pending"
                                    ? styles.paymentBadgePending
                                    : (c.cycleCommitted ?? c.cycleUsed ?? 0) >= getChildQuota(c)
                                    ? styles.paymentBadgeUnpaid
                                    : { background: "#F2F6F2", color: "#7C8A7C" }),
                                }}
                              >
                                {status === "paid" ? "결제완료" : status === "pending" ? "입금확인중" : `${c.cycleUsed || 0}/${getChildQuota(c)}`}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>
        )}

        {tab === "payment" && (
          <div>
            <div style={styles.sectionTitle}>이트랜스퍼 수신 정보</div>
            <EtransferInfoEditor etransferInfo={etransferInfo} onUpdateEtransferInfo={onUpdateEtransferInfo} />

            <div style={{ ...styles.sectionTitle, marginTop: 22 }}>프로모 코드</div>
            <PromoCodeManager
              promoCodes={promoCodes}
              onCreatePromoCode={onCreatePromoCode}
              onTogglePromoCode={onTogglePromoCode}
              onDeletePromoCode={onDeletePromoCode}
            />

            <div style={{ ...styles.adminStatRow, marginTop: 20 }}>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>결제 완료</div>
                <div style={{ ...styles.adminStatValue, color: "#4F7A44" }}>{paidPayments.length}명</div>
              </div>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>입금확인중</div>
                <div style={{ ...styles.adminStatValue, color: "#B5872E" }}>{pendingPayments.length}명</div>
              </div>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>미결제</div>
                <div style={{ ...styles.adminStatValue, color: "#C0392B" }}>{unpaidPayments.length}명</div>
              </div>
            </div>
            <div style={{ ...styles.adminStatRow, marginTop: 10 }}>
              <div style={styles.adminStatCard}>
                <div style={styles.adminStatLabel}>총 수납액</div>
                <div style={styles.adminStatValue}>{formatCAD(totalCollected)}</div>
              </div>
            </div>

            <div style={{ ...styles.sectionTitle, marginTop: 18 }}>결제 현황</div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
              <button
                onClick={() => setPaymentFilter("all")}
                style={{ ...styles.filterChip, ...(paymentFilter === "all" ? styles.filterChipActive : {}) }}
              >
                전체
              </button>
              <button
                onClick={() => setPaymentFilter("partial")}
                style={{ ...styles.filterChip, ...(paymentFilter === "partial" ? styles.filterChipActive : {}) }}
              >
                일부 미납 가정만 ({partialFamilyIds.size})
              </button>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {visiblePayments.length === 0 && (
                <div style={{ fontSize: 13, color: "#9AA39A", padding: "10px 2px" }}>해당하는 결제 내역이 없어요.</div>
              )}
              {visiblePayments.map(({ parent, child, status, amount }) => (
                <div key={child.id} style={styles.adminRow} className="fade-item">
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <div>
                      <div style={{ fontSize: 14.5, fontWeight: 800, color: "#33402F" }}>{child.name}</div>
                      <div style={{ fontSize: 12.5, color: "#7C8A7C", marginTop: 3 }}>
                        {parent.parentName}
                        {status !== "unpaid" && child.payment?.method && <> · e-Transfer</>}
                        {status === "unpaid" && <> · {child.cycleUsed || 0}/{getChildQuota(child)}회 진행 중</>}
                      </div>
                    </div>
                    <div style={{ textAlign: "right" }}>
                      <div style={{ fontSize: 15, fontWeight: 800, color: status === "paid" ? "#4F7A44" : status === "pending" ? "#B5872E" : "#C0392B" }}>
                        {formatCAD(amount)}
                      </div>
                      <div
                        style={{
                          ...styles.paymentBadge,
                          ...(status === "paid" ? styles.paymentBadgePaid : status === "pending" ? styles.paymentBadgePending : styles.paymentBadgeUnpaid),
                          marginTop: 4,
                        }}
                      >
                        {status === "paid" ? "결제완료" : status === "pending" ? "입금확인중" : (child.cycleUsed || 0) >= getChildQuota(child) ? "결제 대상" : "미결제"}
                      </div>
                    </div>
                  </div>
                  {status === "pending" && (
                    <button onClick={() => onApprovePayment(child.payment.id)} style={styles.approveBtn}>
                      입금 확인 · 승인하기
                    </button>
                  )}
                  {status === "paid" && (
                    <button onClick={() => onRevokePayment(child.payment.id)} style={styles.revokeBtn}>
                      승인 취소
                    </button>
                  )}
                  <ResetOrdersButton profileId={parent.id} parentName={parent.parentName} onResetOrders={onResetOrders} />
                  <ServiceStartDateField child={child} onUpdateServiceStartDate={onUpdateServiceStartDate} />
                  <TotalQuotaField child={child} onUpdateTotalQuota={onUpdateTotalQuota} />
                </div>
              ))}
            </div>

            {removedChildPayments && removedChildPayments.length > 0 && (
              <>
                <div style={{ ...styles.sectionTitle, marginTop: 22, color: "#9AA39A" }}>삭제된 자녀의 결제기록</div>
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  {removedChildPayments.map(({ parentName, child, payment }) => (
                    <div key={child.id} style={{ ...styles.adminRow, opacity: 0.7 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                        <div>
                          <div style={{ fontSize: 14, fontWeight: 700, color: "#33402F" }}>{child.name} (삭제됨)</div>
                          <div style={{ fontSize: 12, color: "#9AA39A", marginTop: 2 }}>{parentName}</div>
                        </div>
                        <div
                          style={{
                            ...styles.paymentBadge,
                            ...(payment.status === "paid" ? styles.paymentBadgePaid : styles.paymentBadgePending),
                          }}
                        >
                          {formatCAD(payment.amount)} · {payment.status === "paid" ? "결제완료" : "입금확인중"}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>
        )}
        {tab === "menu" && (
          <AdminMenuEditor
            menusByMonth={menusByMonth}
            onUpdateMenus={onUpdateMenus}
            onDeleteMenuMonth={onDeleteMenuMonth}
            onSendMenuNotification={onSendMenuNotification}
            activeYear={activeYear}
            activeMonth={activeMonth}
          />
        )}
        {tab === "notice" && <AdminNoticeEditor notices={notices} onUpdateNotices={onUpdateNotices} onSendNoticeNotification={onSendNoticeNotification} />}
        {tab === "reviews" && (
          <div>
            <div style={styles.sectionTitle}>학부모 리뷰</div>
            <ReviewsPanel />
          </div>
        )}
        {tab === "settings" && (
          <AdminSettingsView
            pricing={pricing}
            onUpdatePricing={onUpdatePricing}
            deliveryWeekdays={deliveryWeekdays}
            onUpdateDeliveryWeekdays={onUpdateDeliveryWeekdays}
            allProfilesForRole={allProfilesForRole}
            onUpdateProfileRole={onUpdateProfileRole}
            onExportFullBackup={onExportFullBackup}
            activityLog={activityLog}
            onClearActivityLog={onClearActivityLog}
          />
        )}
      </main>

      <nav style={styles.tabbar}>
        <TabButton icon={<User size={20} />} label="전체 현황" active={tab === "overview"} onClick={() => setTab("overview")} />
        <TabButton icon={<CreditCard size={20} />} label="결제현황" active={tab === "payment"} onClick={() => setTab("payment")} />
        <TabButton icon={<UtensilsCrossed size={20} />} label="메뉴관리" active={tab === "menu"} onClick={() => setTab("menu")} />
        <TabButton icon={<Megaphone size={20} />} label="공지사항" active={tab === "notice"} onClick={() => setTab("notice")} />
        <TabButton icon={<Star size={20} />} label="리뷰" active={tab === "reviews"} onClick={() => setTab("reviews")} />
        <TabButton icon={<Settings size={20} />} label="설정" active={tab === "settings"} onClick={() => setTab("settings")} />
      </nav>
    </div>
  );
}

// 복구 이메일이 등록돼 있어야 "비밀번호 찾기"가 동작해요. 등록/변경 상태를 보여주는 작은 위젯이에요.
function RecoveryEmailField({ currentAuthEmail, onUpdateRecoveryEmail, t }) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("idle"); // idle | saving | sent | error
  const hasRecoveryEmail = currentAuthEmail && !currentAuthEmail.endsWith("@meallions.local");

  const handleSave = async () => {
    if (!email.trim()) return;
    setStatus("saving");
    try {
      await onUpdateRecoveryEmail(email.trim());
      setStatus("sent");
    } catch (e) {
      setStatus("error");
    }
  };

  return (
    <div style={{ ...styles.profileCard, marginBottom: 16 }}>
      {hasRecoveryEmail ? (
        <div style={{ fontSize: 13, color: "#4F7A44", fontWeight: 700, marginBottom: 10 }}>
          ✓ {t("profile.recoveryEmailRegistered", { email: currentAuthEmail })}
        </div>
      ) : (
        <p style={{ ...styles.helperText, marginTop: 0 }}>{t("profile.recoveryEmailHelper")}</p>
      )}
      <div style={styles.fieldRow}>
        <label style={styles.fieldLabel}>{t("profile.recoveryEmailLabel")}</label>
        <input
          style={styles.fieldInput}
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder={t("profile.recoveryEmailPlaceholder")}
        />
      </div>
      {status === "sent" && <div style={{ fontSize: 12.5, color: "#4F7A44", marginBottom: 8 }}>{t("profile.recoveryEmailSent")}</div>}
      {status === "error" && <div style={{ fontSize: 12.5, color: "#C0392B", marginBottom: 8 }}>{t("profile.recoveryEmailError")}</div>}
      <button onClick={handleSave} disabled={status === "saving"} style={{ ...styles.checkoutBtn, width: "100%" }}>
        {status === "saving" ? "..." : hasRecoveryEmail ? t("profile.recoveryEmailChange") : t("profile.recoveryEmailRegister")}
      </button>
    </div>
  );
}

// 이 브라우저에서 알림을 받을지 켜고 끄는 토글이에요. 켜면 공지사항·메뉴판 업데이트를
// 앱을 안 켜도 알 수 있어요.
function PushNotificationToggle({ pushStatus, onTogglePush, t }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const handleToggle = async () => {
    setError("");
    setBusy(true);
    try {
      await onTogglePush(pushStatus !== "subscribed");
    } catch (e) {
      setError(e.message || t("profile.notificationsError"));
    }
    setBusy(false);
  };

  if (pushStatus === "unsupported") {
    return (
      <div style={styles.profileCard}>
        <p style={{ ...styles.helperText, marginTop: 0, marginBottom: 0 }}>{t("profile.notificationsUnsupported")}</p>
      </div>
    );
  }

  const isOn = pushStatus === "subscribed";
  return (
    <div style={{ ...styles.profileCard, marginBottom: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12 }}>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: 13.5, fontWeight: 700, color: "#33402F" }}>{t("profile.notificationsLabel")}</div>
          <div style={{ fontSize: 12, color: "#9AA39A", marginTop: 2 }}>{t("profile.notificationsHelper")}</div>
        </div>
        <button
          onClick={handleToggle}
          disabled={busy}
          style={{ ...styles.toggleSwitch, ...(isOn ? styles.toggleSwitchOn : {}), opacity: busy ? 0.6 : 1 }}
        >
          <div style={{ ...styles.toggleKnob, ...(isOn ? styles.toggleKnobOn : {}) }} />
        </button>
      </div>
      {error && <div style={{ fontSize: 12, color: "#C0392B", marginTop: 8 }}>{error}</div>}
    </div>
  );
}

function ProfileView({ account, onUpdateChild, onUpdateAddress, onUpdateRecoveryEmail, currentAuthEmail, onViewPrivacyPolicy, pushStatus, onTogglePush, language, setLanguage, t }) {
  const [children, setChildren] = useState(account.children);
  const [address, setAddress] = useState(account.address || "");
  const [saved, setSaved] = useState(false);
  const isFirstRender = React.useRef(true);

  const updateChild = (idx, key, value) => {
    setChildren((prev) => prev.map((c, i) => (i === idx ? { ...c, [key]: value } : c)));
    setSaved(false);
  };

  const addChild = () => {
    setChildren((prev) => [...prev, { name: "", gender: "남", age: "", allergy: "없음" }]);
    setSaved(false);
  };

  const removeChild = (idx) => {
    setChildren((prev) => prev.filter((_, i) => i !== idx));
    setSaved(false);
  };

  // 실시간 자동 저장: 입력을 멈추면 1초 뒤 자동으로 서버에 저장됩니다 (버튼을 안 눌러도 저장돼요).
  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    const timer = setTimeout(() => {
      onUpdateChild(children);
      onUpdateAddress(address);
      setSaved(true);
      setTimeout(() => setSaved(false), 1800);
    }, 1000);
    return () => clearTimeout(timer);
  }, [children, address]);

  const handleSave = () => {
    onUpdateChild(children);
    onUpdateAddress(address);
    setSaved(true);
    setTimeout(() => setSaved(false), 1800);
  };

  return (
    <div>
      <div style={styles.sectionTitle}>{t("profile.addressTitle")}</div>
      <div style={{ ...styles.profileCard, marginBottom: 16 }}>
        <div style={styles.fieldRow}>
          <label style={styles.fieldLabel}>{t("profile.addressLabel")}</label>
          <input
            style={styles.fieldInput}
            value={address}
            onChange={(e) => { setAddress(e.target.value); setSaved(false); }}
            placeholder={t("signup.addressPlaceholder")}
          />
        </div>
      </div>

      <div style={styles.sectionTitle}>{t("profile.recoveryEmailTitle")}</div>
      <RecoveryEmailField currentAuthEmail={currentAuthEmail} onUpdateRecoveryEmail={onUpdateRecoveryEmail} t={t} />

      <div style={styles.sectionTitle}>{t("profile.languageTitle")}</div>
      <div style={styles.profileCard}>
        <LanguageSelect language={language} setLanguage={setLanguage} t={t} />
      </div>

      <div style={styles.sectionTitle}>{t("profile.notificationsTitle")}</div>
      <PushNotificationToggle pushStatus={pushStatus} onTogglePush={onTogglePush} t={t} />

      <div style={styles.sectionTitle}>{t("profile.childrenTitle")}</div>
      {children.map((form, idx) => (
        <div key={idx} style={{ ...styles.profileCard, marginBottom: 12 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: "#9AA39A" }}>{t("profile.childLabel", { n: idx + 1 })}</div>
            {children.length > 1 && (
              <button onClick={() => removeChild(idx)} style={styles.removeChildBtn}>
                <X size={14} /> {t("common.delete")}
              </button>
            )}
          </div>

          <div style={styles.fieldRow}>
            <label style={styles.fieldLabel}>{t("signup.childNameLabel")}</label>
            <input style={styles.fieldInput} value={form.name} onChange={(e) => updateChild(idx, "name", e.target.value)} />
          </div>

          <div style={styles.fieldRow}>
            <label style={styles.fieldLabel}>{t("signup.genderLabel")}</label>
            <div style={{ display: "flex", gap: 8 }}>
              {[
                { key: "남", label: t("signup.genderMale") },
                { key: "여", label: t("signup.genderFemale") },
              ].map((g) => (
                <button
                  key={g.key}
                  onClick={() => updateChild(idx, "gender", g.key)}
                  style={{
                    ...styles.genderChip,
                    background: form.gender === g.key ? "#4F7A44" : "#F2F6F2",
                    color: form.gender === g.key ? "#fff" : "#5C6A5C",
                  }}
                >
                  {g.label}
                </button>
              ))}
            </div>
          </div>

          <div style={styles.fieldRow}>
            <label style={styles.fieldLabel}>{t("signup.ageLabel")}</label>
            <input
              type="number"
              min="0"
              max="12"
              style={styles.fieldInput}
              value={form.age}
              onChange={(e) => updateChild(idx, "age", e.target.value)}
            />
          </div>

          <div style={styles.fieldRow}>
            <label style={styles.fieldLabel}>{t("signup.allergyLabel")}</label>
            <textarea
              style={{ ...styles.fieldInput, height: 64, resize: "none", paddingTop: 10 }}
              value={form.allergy}
              onChange={(e) => updateChild(idx, "allergy", e.target.value)}
              placeholder={t("signup.allergyPlaceholder")}
            />
          </div>
        </div>
      ))}

      <button onClick={addChild} style={styles.addChildBtn}>{t("signup.addChild")}</button>

      <button onClick={handleSave} style={{ ...styles.checkoutBtn, width: "100%", marginTop: 14 }}>
        {saved ? t("common.saved") : t("common.save")}
      </button>

      <button onClick={onViewPrivacyPolicy} style={styles.privacyLinkBtn}>
        {t("profile.viewPrivacyPolicy")}
      </button>
    </div>
  );
}

function MainApp({ account, menus, menusByMonth, notices, etransferInfo, activeYear, activeMonth, activeKey, activeLabel, onUpdateChild, onUpdateOrder, onUpdatePayment, onCancelPayment, onDismissPaymentNotice, onUpdateAddress, onUpdateRecoveryEmail, currentAuthEmail, onViewPrivacyPolicy, pushStatus, onTogglePush, onLogout, dataError, onDismissDataError, canInstall, onInstallClick, onCopyPreviousMonth, language, setLanguage, t }) {
  const [tab, setTab] = useState("order");
  // 신청 탭은 사이클이 끝나기 1주일 전부터 다음 달 신청도 미리 받을 수 있도록, 이번 달/다음 달을 전환할 수 있어요.
  const [monthOffset, setMonthOffset] = useState(0); // 0 = 이번달, 1 = 다음달
  const viewDate = useMemo(() => new Date(activeYear, activeMonth - 1 + monthOffset, 1), [activeYear, activeMonth, monthOffset]);
  const viewYear = viewDate.getFullYear();
  const viewMonth = viewDate.getMonth() + 1;
  const viewKey = monthKey(viewYear, viewMonth);
  const viewLabel = monthLabelLocalized(viewYear, viewMonth, language);
  const viewMenus = menusByMonth[viewKey] || {};
  const availableDays = useMemo(() => Object.keys(viewMenus).filter((d) => !viewMenus[d].isHoliday).map(Number).sort((a, b) => a - b), [viewMenus]);
  // 선결제 원칙: 아직 한 번도 결제한 적 없는 자녀가 있으면, 결제 전까지는 캘린더 기본값을
  // "전부 신청됨"이 아니라 "아무것도 없음"으로 보여줘요 (아직 쓸 수 있는 사이클 자체가 없으니까요).
  const hasNeverPaidChild = account.children.some((c) => !c.hasEverPaid);
  const defaultDays = hasNeverPaidChild ? [] : availableDays;
  const [selected, setSelected] = useState(new Set((account.ordersByMonth && account.ordersByMonth[viewKey]) || defaultDays));
  // 이번 달 ↔ 다음 달 전환 시, 그리고 (관리자의 신청 초기화 등으로) 백그라운드에서 저장된 값이 바뀌었을 때도
  // 그 달에 저장된 신청 내역(없으면 배송일 전체, 단 미결제면 빈 캘린더)으로 다시 맞춰줘요.
  const savedForView = account.ordersByMonth && account.ordersByMonth[viewKey];
  const savedForViewKey = savedForView ? savedForView.join(",") : "";
  useEffect(() => {
    setSelected(new Set(savedForView || defaultDays));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [viewKey, savedForViewKey]);
  const [detailDay, setDetailDay] = useState(null);
  // 마감 48시간 이내로 다가온 신청/스킵 건이 있으면 알려줘요. (실제 오늘 기준 이번 달 마감만 알려줘요)
  const currentMenus = menusByMonth[activeKey] || {};
  const currentAvailableDays = useMemo(() => Object.keys(currentMenus).filter((d) => !currentMenus[d].isHoliday).map(Number).sort((a, b) => a - b), [currentMenus]);
  const upcomingDeadline = useMemo(() => getUpcomingDeadline(currentAvailableDays, activeYear, activeMonth, 48), [currentAvailableDays, activeYear, activeMonth]);
  const [dismissDeadlineBanner, setDismissDeadlineBanner] = useState(false);
  useEffect(() => {
    if (!upcomingDeadline) setDismissDeadlineBanner(false);
  }, [upcomingDeadline]);
  // 결제할 자녀를 체크박스로 선택 — 체크한 인원 수만큼 $126씩 곱해서 한 번에 결제해요.
  const [selectedChildIds, setSelectedChildIds] = useState(
    () =>
      new Set(
        account.children
          .filter((c) => (c.payment?.status || "unpaid") === "unpaid" && (c.cycleCommitted ?? c.cycleUsed ?? 0) >= getChildQuota(c))
          .map((c) => c.id)
      )
  );
  const [showPayment, setShowPayment] = useState(false);
  const [showReview, setShowReview] = useState(false);
  const [copyingPrevMonth, setCopyingPrevMonth] = useState(false);

  const handleCopyPreviousMonthClick = async () => {
    if (hasNeverPaidChild) {
      const unpaidChild = account.children.find((c) => !c.hasEverPaid);
      setQuotaBlockedMsg(t("order.needsFirstPayment", { name: unpaidChild?.name }));
      setTimeout(() => setQuotaBlockedMsg(""), 3500);
      return;
    }
    setCopyingPrevMonth(true);
    const ratioByWeekday = await onCopyPreviousMonth(viewYear, viewMonth);
    if (ratioByWeekday) {
      const newSelected = new Set(
        availableDays.filter((d) => {
          const wd = getWeekday(viewYear, viewMonth, d);
          return (ratioByWeekday[wd] ?? 1) >= 0.5;
        })
      );
      setSelected(newSelected);
      onUpdateOrder(viewKey, [...newSelected]);
    }
    setCopyingPrevMonth(false);
  };

  // 이번 달(또는 다음 달) 신청 전체를 처음부터 다시 고를 수 있도록 싹 비워줘요 (전부 스킵 상태로).
  const handleClearSelection = () => {
    setSelected(new Set());
    onUpdateOrder(viewKey, []);
  };

  const usedCount = selected.size; // 이번 달 신청 날짜 수 — 참고용 표시일 뿐, 결제 사이클과는 무관해요.
  // 결제는 자녀별로 "마지막 결제 이후 12회를 채웠는지"로 판단해요 (달과 무관하게 누적).
  const childrenDue = account.children.filter(
    (c) => (c.payment?.status || "unpaid") === "unpaid" && (c.cycleCommitted ?? c.cycleUsed ?? 0) >= getChildQuota(c)
  );
  const quotaFullyUsed = childrenDue.length > 0;
  const [dismissQuotaBanner, setDismissQuotaBanner] = useState(false);
  useEffect(() => {
    if (!quotaFullyUsed) setDismissQuotaBanner(false); // 다시 미달 상태가 되면 닫힘 상태 초기화
  }, [quotaFullyUsed]);
  const toggleChildSelection = (childId) => {
    setSelectedChildIds((prev) => {
      const next = new Set(prev);
      if (next.has(childId)) next.delete(childId);
      else next.add(childId);
      return next;
    });
  };
  // 결제가 완료/대기중으로 바뀐 자녀는 체크 목록에서 자동으로 빼줍니다.
  // (안 그러면 이미 낸 자녀가 선택된 채로 남아 합계·중복결제 버그로 이어질 수 있어요)
  useEffect(() => {
    setSelectedChildIds((prev) => {
      const stillUnpaidIds = new Set(
        account.children.filter((c) => (c.payment?.status || "unpaid") === "unpaid").map((c) => c.id)
      );
      const next = new Set([...prev].filter((id) => stillUnpaidIds.has(id)));
      return next.size === prev.size ? prev : next;
    });
  }, [account.children]);
  const childrenToPay = account.children.filter((c) => selectedChildIds.has(c.id) && (c.payment?.status || "unpaid") === "unpaid");

  // 다자녀 중 한 명이라도 서비스 시작 전이면, 그 날짜까지는 가족 전체 캘린더를 잠가요.
  const familyServiceStartDate = account.children.reduce((latest, c) => {
    if (!c.service_start_date) return latest;
    return !latest || c.service_start_date > latest ? c.service_start_date : latest;
  }, null);
  const isBeforeServiceStart = (year, month, day) => {
    if (!familyServiceStartDate) return false;
    const dateStr = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    return dateStr < familyServiceStartDate;
  };

  const [quotaBlockedMsg, setQuotaBlockedMsg] = useState("");
  const toggleDay = (day) => {
    if (isSkipLocked(viewYear, viewMonth, day) || isBeforeServiceStart(viewYear, viewMonth, day)) return;
    const isAdding = !selected.has(day);
    if (isAdding) {
      // 선결제 원칙: 한 번도 결제한 적 없는 자녀가 있으면, 먼저 결제해야만 신청을 시작할 수 있게 막아요.
      const unpaidNewChild = account.children.find((c) => !c.hasEverPaid);
      if (unpaidNewChild) {
        setQuotaBlockedMsg(t("order.needsFirstPayment", { name: unpaidNewChild.name }));
        setTimeout(() => setQuotaBlockedMsg(""), 3500);
        return;
      }
      // 이미 (실제 배송 여부와 상관없이) 체크해둔 날짜 총합이 사이클 횟수를 다 채웠고 아직 결제 안 한
      // 자녀가 있으면, 더 이상 신청을 추가할 수 없게 막아요. (이미 선택했던 날짜를 취소하는 건 계속 가능해요.)
      const blockedChild = account.children.find(
        (c) => (c.payment?.status || "unpaid") === "unpaid" && (c.cycleCommitted ?? c.cycleUsed ?? 0) >= getChildQuota(c)
      );
      if (blockedChild) {
        setQuotaBlockedMsg(t("order.quotaBlocked", { name: blockedChild.name }));
        setTimeout(() => setQuotaBlockedMsg(""), 3500);
        return;
      }
    }
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(day)) {
        next.delete(day);
      } else {
        next.add(day);
      }
      onUpdateOrder(viewKey, [...next]);
      return next;
    });
  };

  const weeks = useMemo(() => {
    const total = daysInMonth(viewYear, viewMonth);
    const firstWd = firstWeekdayOfMonth(viewYear, viewMonth);
    const cells = [];
    for (let i = 0; i < firstWd; i++) cells.push(null);
    for (let d = 1; d <= total; d++) cells.push(d);
    while (cells.length % 7 !== 0) cells.push(null);
    const rows = [];
    for (let i = 0; i < cells.length; i += 7) rows.push(cells.slice(i, i + 7));
    return rows;
  }, [viewYear, viewMonth]);

  return (
    <div style={styles.app}>
      <style>{`
        * { box-sizing: border-box; }
        body { margin: 0; }
        @keyframes riseIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        .fade-item { animation: riseIn 0.25s ease both; }
        .spin { animation: spin 0.8s linear infinite; }
      `}</style>

      <header style={styles.header}>
        <div style={styles.headerTop}>
          <img src={LOGO_SRC} alt="MEALLIONS" style={styles.logoImgHeader} />
          <div style={{ flex: 1 }} />
          {canInstall && (
            <button onClick={onInstallClick} style={styles.installBtn} title={t("common.install")}>
              {t("common.install")}
            </button>
          )}
          <LanguageSelect language={language} setLanguage={setLanguage} t={t} compact />
          <button onClick={forceAppRefresh} style={styles.logoutBtn} title="새로고침">
            <RefreshCw size={16} color="#4F7A44" />
          </button>
          <button onClick={onLogout} style={styles.logoutBtn}>
            <LogOut size={16} color="#4F7A44" />
          </button>
        </div>
      </header>

      {dataError && (
        <div style={styles.dataErrorBanner}>
          <span>{dataError}</span>
          <button onClick={onDismissDataError} style={styles.paymentNoticeClose}>
            <X size={16} />
          </button>
        </div>
      )}

      {upcomingDeadline && !dismissDeadlineBanner && (
        <div style={styles.deadlineBanner}>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 800, fontSize: 14 }}>{t("banner.deadlineTitle")}</div>
            <div style={{ fontSize: 12.5, marginTop: 2, opacity: 0.9 }}>
              {t("banner.deadlineMsg", {
                date: upcomingDeadline.toLocaleString(
                  t("common.locale"),
                  { month: "long", day: "numeric", hour: "numeric", minute: "2-digit" }
                ),
              })}
            </div>
          </div>
          <button onClick={() => setDismissDeadlineBanner(true)} style={styles.paymentNoticeClose}>
            <X size={16} />
          </button>
        </div>
      )}

      {quotaFullyUsed && !dismissQuotaBanner && (
        <div style={styles.quotaReachedBanner}>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 800, fontSize: 14 }}>{t("banner.quotaReachedTitle")}</div>
            <div style={{ fontSize: 12.5, marginTop: 2, opacity: 0.9 }}>
              {childrenDue.map((c) => c.name).join(", ")} · {t("banner.quotaReachedMsg", { n: getChildQuota(childrenDue[0]) })}
            </div>
          </div>
          <button onClick={() => setTab("payment")} style={styles.quotaReachedBtn}>{t("banner.goToPayment")}</button>
          <button onClick={() => setDismissQuotaBanner(true)} style={styles.paymentNoticeClose}>
            <X size={16} />
          </button>
        </div>
      )}

      {account.children.map((child) => (
        <React.Fragment key={child.id}>
          {child.payment?.status === "paid" && child.payment?.notified === false && (
            <div style={styles.paymentNoticeBanner}>
              <div>
                <div style={{ fontWeight: 800, fontSize: 14 }}>{t("banner.approvedTitle")}</div>
                <div style={{ fontSize: 12.5, marginTop: 2, opacity: 0.9 }}>
                  {child.name} · {t("banner.approvedMsg", { amount: formatCAD(child.payment.amount || calcFee(1).total) })}
                </div>
              </div>
              <button onClick={() => onDismissPaymentNotice(child.id, child.payment.id)} style={styles.paymentNoticeClose}>
                <X size={16} />
              </button>
            </div>
          )}
          {child.payment?.status === "pending" && (
            <div style={styles.pendingNoticeBanner}>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 800, fontSize: 14 }}>{t("banner.pendingTitle")}</div>
                <div style={{ fontSize: 12.5, marginTop: 2, opacity: 0.9 }}>
                  {child.name} · {t("banner.pendingMsg", { amount: formatCAD(child.payment.amount || calcFee(1).total) })}
                </div>
              </div>
              <button onClick={() => onCancelPayment(child.id, child.payment.id)} style={styles.cancelPaymentBtn}>
                {t("payment.cancelSubmit")}
              </button>
            </div>
          )}
        </React.Fragment>
      ))}

      <main style={styles.main}>
        {tab === "order" && (
          <OrderView
            weeks={weeks}
            menus={viewMenus}
            availableDays={availableDays}
            activeYear={viewYear}
            activeMonth={viewMonth}
            monthLabel={viewLabel}
            monthOffset={monthOffset}
            onPrevMonth={() => setMonthOffset((o) => Math.max(0, o - 1))}
            onNextMonth={() => setMonthOffset((o) => Math.min(1, o + 1))}
            selected={selected}
            toggleDay={toggleDay}
            usedCount={usedCount}
            familyChildren={account.children}
            quotaBlockedMsg={quotaBlockedMsg}
            setDetailDay={setDetailDay}
            isBeforeServiceStart={isBeforeServiceStart}
            onCopyPreviousMonth={handleCopyPreviousMonthClick}
            copyingPrevMonth={copyingPrevMonth}
            onClearSelection={handleClearSelection}
            t={t}
          />
        )}
        {tab === "menuBoard" && (
          <MenuBoardView menusByMonth={menusByMonth} activeYear={activeYear} activeMonth={activeMonth} language={language} t={t} />
        )}
        {tab === "payment" && (
          <PaymentView
            children={account.children}
            selectedChildIds={selectedChildIds}
            onToggleChild={toggleChildSelection}
            onCheckout={() => setShowPayment(true)}
            t={t}
          />
        )}
        {tab === "notice" && <NoticeView notices={notices} t={t} />}
        {tab === "profile" && <ProfileView account={account} onUpdateChild={onUpdateChild} onUpdateAddress={onUpdateAddress} onUpdateRecoveryEmail={onUpdateRecoveryEmail} currentAuthEmail={currentAuthEmail} onViewPrivacyPolicy={onViewPrivacyPolicy} pushStatus={pushStatus} onTogglePush={onTogglePush} language={language} setLanguage={setLanguage} t={t} />}
      </main>

      {detailDay && viewMenus[detailDay] && (
        <DayDetailSheet
          day={detailDay}
          monthLabel={monthDayLabelLocalized(viewYear, viewMonth, detailDay, language)}
          menu={viewMenus[detailDay]}
          isSelected={selected.has(detailDay)}
          locked={isSkipLocked(viewYear, viewMonth, detailDay) || isBeforeServiceStart(viewYear, viewMonth, detailDay)}
          lockedReason={isBeforeServiceStart(viewYear, viewMonth, detailDay) ? "serviceNotStarted" : "deadline"}
          onToggle={() => toggleDay(detailDay)}
          onClose={() => setDetailDay(null)}
          t={t}
        />
      )}

      {showPayment && childrenToPay.length > 0 && (
        <PaymentSheet
          children={childrenToPay}
          etransferInfo={etransferInfo}
          onClose={() => setShowPayment(false)}
          onValidatePromoCode={api.validatePromoCode}
          onPaid={async (perChildAmount, method, promo) => {
            const results = await Promise.all(
              childrenToPay.map((c) => onUpdatePayment(c.id, { amount: perChildAmount, promo, method }))
            );
            const allOk = results.every(Boolean);
            if (allOk) setShowReview(true); // 결제 제출 성공 직후 리뷰 팝업을 띄워요 (원치 않으면 X로 닫을 수 있어요)
            return allOk;
          }}
          t={t}
        />
      )}

      {showReview && (
        <ReviewPopup
          onClose={() => setShowReview(false)}
          onSubmit={async ({ serviceRating, qualityRating, kidsRating, comment }) => {
            try {
              await api.submitReview({ profileId: account.id, serviceRating, qualityRating, kidsRating, comment });
              return true;
            } catch (e) {
              return false;
            }
          }}
          t={t}
        />
      )}

      <nav style={styles.tabbar}>
        <TabButton icon={<CalendarDays size={19} />} label={t("tabs.order")} active={tab === "order"} onClick={() => setTab("order")} />
        <TabButton icon={<UtensilsCrossed size={19} />} label={t("tabs.menuBoard")} active={tab === "menuBoard"} onClick={() => setTab("menuBoard")} />
        <TabButton icon={<CreditCard size={19} />} label={t("tabs.payment")} active={tab === "payment"} onClick={() => setTab("payment")} />
        <TabButton icon={<Megaphone size={19} />} label={t("tabs.notice")} active={tab === "notice"} onClick={() => setTab("notice")} />
        <TabButton icon={<User size={19} />} label={t("tabs.profile")} active={tab === "profile"} onClick={() => setTab("profile")} />
      </nav>
    </div>
  );
}

function TabButton({ icon, label, active, onClick }) {
  return (
    <button onClick={onClick} style={{ ...styles.tabBtn, color: active ? "#4F7A44" : "#9AA39A" }}>
      {icon}
      <span style={{ fontSize: 9.5, marginTop: 2, fontWeight: active ? 700 : 500 }}>{label}</span>
    </button>
  );
}

function OrderView({ weeks, menus, availableDays, activeYear, activeMonth, monthLabel: viewMonthLabel, monthOffset, onPrevMonth, onNextMonth, selected, toggleDay, usedCount, familyChildren, quotaBlockedMsg, setDetailDay, isBeforeServiceStart, onCopyPreviousMonth, copyingPrevMonth, onClearSelection, t }) {
  return (
    <div>
      {typeof monthOffset === "number" && (
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
          <button onClick={onPrevMonth} disabled={monthOffset === 0} style={{ ...styles.iconBtn, opacity: monthOffset === 0 ? 0.35 : 1 }}>
            <ChevronLeft size={18} />
          </button>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#33402F" }}>
            {viewMonthLabel} {monthOffset === 1 && <span style={{ fontSize: 11.5, fontWeight: 700, color: "#4F7A44", marginLeft: 4 }}>{t("order.nextCycleBadge")}</span>}
          </div>
          <button onClick={onNextMonth} disabled={monthOffset === 1} style={{ ...styles.iconBtn, opacity: monthOffset === 1 ? 0.35 : 1 }}>
            <ChevronRight size={18} />
          </button>
        </div>
      )}
      <div style={styles.quotaCard}>
        <div>
          <div style={styles.quotaLabel}>{t("order.usedTitle")}</div>
          <div style={styles.quotaNums}>
            <span style={{ fontSize: 28, fontWeight: 800, color: "#4F7A44" }}>{usedCount}</span>
            <span style={{ fontSize: 16, color: "#7C8A7C" }}> {t("order.daysUnit")}</span>
          </div>
        </div>
        <div style={styles.quotaRight}>
          <div style={{ ...styles.quotaBadge, background: "#E7F3EA", color: "#4F7A44" }}>{t("order.cycleHint")}</div>
        </div>
      </div>

      {familyChildren && familyChildren.some((c) => !c.hasEverPaid) && (
        <div style={{ fontSize: 12.5, color: "#C0392B", background: "#FCEBE9", borderRadius: 10, padding: "10px 12px", marginBottom: 10, fontWeight: 600 }}>
          {t("order.needsFirstPayment", { name: familyChildren.find((c) => !c.hasEverPaid)?.name })}
        </div>
      )}

      {familyChildren && familyChildren.length > 0 && (
        <div style={{ ...styles.profileCard, marginTop: 10, marginBottom: 4 }}>
          <div style={{ fontSize: 12.5, fontWeight: 700, color: "#7C8A7C", marginBottom: 10 }}>{t("order.cycleStatusTitle")}</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            {familyChildren.map((child) => {
              const quota = getChildQuota(child);
              // 결제 시점 판단과 똑같이(선불이라 체크한 개수 기준), 여기 진행률도 신청해둔 총합으로 보여줘요.
              const used = child.cycleCommitted ?? child.cycleUsed ?? 0;
              const remaining = Math.max(0, quota - used);
              const percent = Math.min(100, Math.round((used / quota) * 100));
              const isDue = !child.hasEverPaid || used >= quota;
              const isSoon = !isDue && remaining <= quota * 0.3;
              const barColor = isDue ? "#C0392B" : isSoon ? "#D97757" : "#4F7A44";
              const statusText = isDue ? t("order.statusDue") : isSoon ? t("order.statusSoon") : t("order.statusNormal");
              const statusBg = isDue ? "#FCEBE9" : isSoon ? "#FDF1DD" : "#E7F3EA";
              return (
                <div key={child.id}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 5 }}>
                    <div style={{ fontSize: 13.5, fontWeight: 700, color: "#33402F" }}>{child.name}</div>
                    <div style={{ fontSize: 10.5, fontWeight: 800, color: barColor, background: statusBg, borderRadius: 6, padding: "2px 7px" }}>
                      {statusText}
                    </div>
                  </div>
                  <div style={{ height: 8, background: "#F0F2EF", borderRadius: 6, overflow: "hidden" }}>
                    <div style={{ height: "100%", width: `${percent}%`, background: barColor, borderRadius: 6, transition: "width 0.3s ease" }} />
                  </div>
                  <div style={{ fontSize: 11.5, color: "#9AA39A", marginTop: 4, display: "flex", justifyContent: "space-between" }}>
                    <span>{t("order.used", { used })} {t("order.totalCount", { total: quota })}</span>
                    <span style={{ fontWeight: 700, color: barColor }}>{t("order.remaining", { remaining })}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <button onClick={onCopyPreviousMonth} disabled={copyingPrevMonth} style={styles.copyPrevMonthBtn}>
        {copyingPrevMonth ? <Loader2 size={14} className="spin" /> : null} {t("order.copyPrevMonth")}
      </button>
      <ClearSelectionButton onClear={onClearSelection} t={t} />
      <p style={styles.helperText}>
        {t("order.deliveryHelper")}
        <br />{t("order.lockHelper")}
      </p>

      {availableDays.length === 0 && (
        <div style={{ fontSize: 13, color: "#9AA39A", padding: "16px 2px", textAlign: "center", background: "#F7F9F6", borderRadius: 12, marginBottom: 10 }}>
          {t("order.menuNotReady", { month: viewMonthLabel })}
        </div>
      )}

      {quotaBlockedMsg && (
        <div style={{ fontSize: 12.5, color: "#C0392B", background: "#FDECEA", borderRadius: 10, padding: "10px 12px", marginBottom: 10, fontWeight: 600 }}>
          {quotaBlockedMsg}
        </div>
      )}

      <div style={styles.legendRow}>
        <span style={styles.legendItem}><span style={{ ...styles.legendDot, background: "#4F7A44" }} />{t("order.selected")}</span>
        <span style={styles.legendItem}><span style={{ ...styles.legendDot, background: "#F2F6F2", border: "1px solid #D8E0D8" }} />{t("order.unselected")}</span>
      </div>

      <div style={styles.calendarCard}>
        <div style={styles.weekRow}>
          {WEEKDAYS.map((w, i) => (
            <div key={w} style={{ ...styles.weekCell, color: i === 0 ? "#D97757" : i === 6 ? "#3E6BC7" : "#9AA39A" }}>
              {t(`weekday.${i}`)}
            </div>
          ))}
        </div>
        {weeks.map((row, ri) => (
          <div key={ri} style={styles.weekRow}>
            {row.map((day, ci) => {
              if (!day) return <div key={ci} style={styles.dayCell} />;
              const isHolidayDay = !!menus[day]?.isHoliday;
              const hasMenu = !!menus[day] && !isHolidayDay;
              const canOpenDetail = !!menus[day]; // 공휴일도 탭하면 안내 문구는 볼 수 있어요
              const isSel = selected.has(day);
              const locked = hasMenu && (isSkipLocked(activeYear, activeMonth, day) || isBeforeServiceStart(activeYear, activeMonth, day));
              return (
                <button
                  key={ci}
                  onClick={() => (canOpenDetail ? setDetailDay(day) : null)}
                  disabled={!canOpenDetail}
                  style={{
                    ...styles.dayCell,
                    cursor: canOpenDetail ? "pointer" : "default",
                    background: isHolidayDay ? "#FCEBE9" : !hasMenu ? "transparent" : isSel ? "#4F7A44" : "#F2F6F2",
                    color: isHolidayDay ? "#D9756B" : !hasMenu ? "#C9CFC9" : isSel ? "#fff" : "#33402F",
                    opacity: locked ? 0.55 : 1,
                  }}
                >
                  <span style={{ fontSize: 14, fontWeight: isSel || isHolidayDay ? 700 : 500 }}>{day}</span>
                  {hasMenu && !locked && <span style={{ ...styles.dot, background: isSel ? "#fff" : "#4F7A44" }} />}
                  {locked && <span style={{ fontSize: 9 }}>🔒</span>}
                  {isHolidayDay && <span style={{ fontSize: 9 }}>🇨🇦</span>}
                </button>
              );
            })}
          </div>
        ))}
      </div>

      <p style={{ ...styles.helperText, textAlign: "center" }}>{t("order.tapForMenu")}</p>
    </div>
  );
}

// 이번 달(보고 있는 달) 신청 전체를 처음부터 다시 고를 수 있도록 싹 비우는 버튼이에요.
// 실수로 누르지 않도록 한 번 누르면 "정말요?" 문구로 바뀌고, 다시 눌러야 확정돼요.
function ClearSelectionButton({ onClear, t }) {
  const [armed, setArmed] = useState(false);

  const handleClick = () => {
    if (!armed) {
      setArmed(true);
      setTimeout(() => setArmed(false), 4000);
      return;
    }
    onClear();
    setArmed(false);
  };

  return (
    <button
      onClick={handleClick}
      style={{
        ...styles.copyPrevMonthBtn,
        marginTop: 8,
        background: armed ? "#FCE4E1" : styles.copyPrevMonthBtn.background,
        color: armed ? "#C0392B" : styles.copyPrevMonthBtn.color,
        border: armed ? "1.5px solid #F2C9C2" : styles.copyPrevMonthBtn.border,
      }}
    >
      {armed ? t("order.clearSelectionConfirm") : t("order.clearSelection")}
    </button>
  );
}

// 메뉴판 — 이번 달 메뉴를 메인·사이드·과일 3가지로 한눈에 보기 쉽게 보여주는 전용 화면
function MenuBoardView({ menusByMonth, activeYear, activeMonth, language, t }) {
  const [offset, setOffset] = useState(0); // 0=이번달, 1=다음달
  const viewDate = new Date(activeYear, activeMonth - 1 + offset, 1);
  const viewYear = viewDate.getFullYear();
  const viewMonth = viewDate.getMonth() + 1;
  const viewKey = monthKey(viewYear, viewMonth);
  const menus = menusByMonth[viewKey] || {};
  const availableDays = Object.keys(menus).map(Number).sort((a, b) => a - b);

  // 날짜를 "몇 번째 주"인지로 묶어서, 한 주(월·화·목)를 가로로 한눈에 볼 수 있게 구성해요.
  const firstWd = firstWeekdayOfMonth(viewYear, viewMonth);
  const weekGroups = {};
  availableDays.forEach((day) => {
    const weekIndex = Math.floor((day - 1 + firstWd) / 7);
    if (!weekGroups[weekIndex]) weekGroups[weekIndex] = {};
    weekGroups[weekIndex][getWeekday(viewYear, viewMonth, day)] = day;
  });
  const weekIndexes = Object.keys(weekGroups).map(Number).sort((a, b) => a - b);
  // DELIVERY_WEEKDAYS는 관리자가 설정한 배송 요일(모듈 전역값)을 그대로 사용해요.

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6 }}>
        <div style={styles.sectionTitle}>{monthLabelLocalized(viewYear, viewMonth, language)} {t("menuBoard.title")}</div>
        <div style={{ display: "flex", gap: 4 }}>
          <button onClick={() => setOffset((o) => Math.max(0, o - 1))} disabled={offset === 0} style={{ ...styles.iconBtn, opacity: offset === 0 ? 0.4 : 1 }}>
            <ChevronLeft size={16} />
          </button>
          <button onClick={() => setOffset((o) => Math.min(1, o + 1))} disabled={offset === 1} style={{ ...styles.iconBtn, opacity: offset === 1 ? 0.4 : 1 }}>
            <ChevronRight size={16} />
          </button>
        </div>
      </div>
      <p style={styles.helperText}>{t("menuBoard.helper")}</p>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        {weekIndexes.map((wi, rowIdx) => (
          <div key={wi} className="fade-item">
            <div style={styles.menuBoardWeekLabel}>{t("menuBoard.week", { n: rowIdx + 1 })}</div>
            <div style={styles.menuBoardWeekRow}>
              {DELIVERY_WEEKDAYS.map((wd) => {
                const day = weekGroups[wi][wd];
                const menu = day ? menus[day] : null;
                return (
                  <div key={wd} style={styles.menuBoardDayCol}>
                    <div style={styles.menuBoardDayHeader}>
                      <span style={{ fontSize: 13, color: "#9AA39A" }}>{t(`weekday.${wd}`)}</span>
                      {day && <span style={{ fontSize: 18, fontWeight: 800, color: "#33402F", marginLeft: 4 }}>{day}</span>}
                    </div>
                    {menu?.isHoliday ? (
                      <div style={styles.holidayCell}>{menu.holidayLabel}</div>
                    ) : menu ? (
                      <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 5, marginTop: 6 }}>
                        <div style={styles.menuBoardCompactRow}>
                          <span style={styles.menuBoardTag}>{t("menuBoard.main")}</span>
                          <span style={styles.menuBoardValueSmall}>{menu.main}</span>
                        </div>
                        <div style={styles.menuBoardCompactRow}>
                          <span style={{ ...styles.menuBoardTag, background: "#EAF1FB", color: "#3E6BC7" }}>{t("menuBoard.side")}</span>
                          <span style={styles.menuBoardValueSmall}>{menu.side}</span>
                        </div>
                        <div style={styles.menuBoardCompactRow}>
                          <span style={{ ...styles.menuBoardTag, background: "#FDF1DD", color: "#B5872E" }}>{t("menuBoard.fruit")}</span>
                          <span style={styles.menuBoardValueSmall}>{menu.fruit || t("menuBoard.none")}</span>
                        </div>
                      </div>
                    ) : (
                      <div style={{ fontSize: 11.5, color: "#C9CFC9", marginTop: 10, textAlign: "center" }}>—</div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}
        {availableDays.length === 0 && (
          <div style={{ fontSize: 13, color: "#9AA39A", padding: "20px 2px", textAlign: "center" }}>{t("menuBoard.empty")}</div>
        )}
      </div>
    </div>
  );
}

// 결제 — 자녀를 체크해서 한 번에 결제하는 전용 화면
function PaymentView({ children, selectedChildIds, onToggleChild, onCheckout, t }) {
  const EARLY_PAY_RATIO = 0.3; // 사이클이 끝나기 전이어도, 남은 횟수가 자녀별 총 횟수의 30% 이하면(예: 12회면 9회 사용 시점부터, 6회면 4회 사용 시점부터) 미리 결제할 수 있어요.
  return (
    <div>
      <div style={styles.sectionTitle}>{t("payment.title")}</div>
      <p style={styles.helperText}>{t("payment.cycleHelper", { n: TOTAL_QUOTA })}</p>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {children.map((child) => {
          const childQuota = getChildQuota(child);
          const status = child.payment?.status || "unpaid";
          const checked = selectedChildIds.has(child.id);
          // 선불 서비스라서, 결제 시점은 "실제 배송된 날짜"가 아니라 "이미 체크(신청)해둔 날짜 총합"
          // 기준으로 판단해요. 도시락을 받고 나서 결제하게 되면 사실상 후불이 되어버리니까요.
          const cycleUsed = child.cycleCommitted ?? child.cycleUsed ?? 0;
          const remaining = Math.max(0, childQuota - cycleUsed);
          const alreadyHandled = status !== "unpaid"; // 이미 결제완료/입금확인중
          // 선결제 원칙: 한 번도 결제한 적 없는 자녀는 신청을 아직 안 했어도(못 했으니까) 바로 결제할 수 있어야 해요.
          const eligibleEarly = !alreadyHandled && (!child.hasEverPaid || remaining <= childQuota * EARLY_PAY_RATIO); // 사이클 종료 전이어도 30% 이하로 남았으면 결제 가능
          const isDue = !child.hasEverPaid || cycleUsed >= childQuota;
          const locked = alreadyHandled || !eligibleEarly; // 아직 많이 남았으면 선택 불가(회색 처리)
          return (
            <button
              key={child.id}
              onClick={() => !locked && onToggleChild(child.id)}
              disabled={locked}
              style={{ ...styles.agendaRow, cursor: locked ? "default" : "pointer", opacity: locked ? 0.6 : 1 }}
              className="fade-item"
            >
              <div
                style={{
                  ...styles.checkbox,
                  ...(checked && !locked ? styles.checkboxChecked : {}),
                  flexShrink: 0,
                }}
              >
                {checked && !locked && <Check size={12} color="#fff" />}
              </div>
              <div style={{ ...styles.agendaTextCol, marginLeft: 10 }}>
                <div style={{ fontSize: 14, fontWeight: 700, color: "#33402F" }}>{child.name}</div>
                <div style={{ fontSize: 12, color: "#9AA39A", marginTop: 1 }}>{formatCAD(calcFee(1).total)}</div>
                {!alreadyHandled && (
                  <div style={{ fontSize: 11.5, color: isDue || eligibleEarly ? "#4F7A44" : "#9AA39A", marginTop: 2, fontWeight: isDue || eligibleEarly ? 700 : 500 }}>
                    {isDue ? t("payment.dueNow") : eligibleEarly ? t("payment.earlyPayAvailable", { used: cycleUsed, total: childQuota }) : t("payment.cycleProgress", { used: cycleUsed, total: childQuota })}
                  </div>
                )}
                {alreadyHandled && (
                  <div style={{ fontSize: 11, color: "#4F7A44", marginTop: 3, lineHeight: 1.4 }}>
                    {t("payment.alreadyPaidNotice", { remaining })}
                  </div>
                )}
              </div>
              {alreadyHandled && (
                <div
                  style={{
                    ...styles.paymentBadge,
                    ...(status === "paid" ? styles.paymentBadgePaid : styles.paymentBadgePending),
                  }}
                >
                  {status === "paid" ? t("order.payDone") : t("order.payWaiting")}
                </div>
              )}
            </button>
          );
        })}
      </div>

      <div style={styles.payoutCard}>
        <div>
          <div style={{ fontSize: 12.5, color: "#7C8A7C" }}>{t("payment.total")}</div>
          <div style={{ fontSize: 20, fontWeight: 800, color: "#33402F", marginTop: 2 }}>
            {formatCAD(calcFee(selectedChildIds.size).total)}
          </div>
          <div style={{ fontSize: 12, color: "#9AA39A", marginTop: 2 }}>
            ({formatCAD(MONTHLY_FEE)} + {(TAX_RATE * 100).toFixed(TAX_RATE * 100 % 1 === 0 ? 0 : 1)}%) × {selectedChildIds.size}
          </div>
        </div>
        <button
          onClick={onCheckout}
          disabled={selectedChildIds.size === 0}
          style={{ ...styles.checkoutBtn, opacity: selectedChildIds.size === 0 ? 0.5 : 1 }}
        >
          {t("order.payBtn")}
        </button>
      </div>
    </div>
  );
}

