const INITIAL_ETRANSFER_INFO = { recipient: "MEALLIONS Inc.", email: "payments@meallions.ca", securityAnswer: "" }; // TODO: 실제 이트랜스퍼 정보로 교체

function PaymentSheet({ children, etransferInfo, onClose, onPaid, onValidatePromoCode, t }) {
  const [status, setStatus] = useState("idle"); // idle | processing | done
  const [copied, setCopied] = useState(false);
  const [promoInput, setPromoInput] = useState("");
  const [appliedPromo, setAppliedPromo] = useState(null); // { code, discountType, discountValue }
  const [promoError, setPromoError] = useState("");
  const [validatingPromo, setValidatingPromo] = useState(false);
  const fee = calcFee(children.length);
  const discount = appliedPromo
    ? appliedPromo.discountType === "percent"
      ? Math.round(fee.total * (appliedPromo.discountValue / 100) * 100) / 100
      : Math.min(appliedPromo.discountValue, fee.total)
    : 0;
  const amount = Math.max(0, fee.total - discount);
  const method = "etransfer";
  const childNames = children.map((c) => c.name).join(", ");

  const handleApplyPromo = async () => {
    if (!promoInput.trim()) return;
    setValidatingPromo(true);
    setPromoError("");
    try {
      const result = await onValidatePromoCode(promoInput);
      if (result.valid) {
        setAppliedPromo(result);
      } else {
        setAppliedPromo(null);
        setPromoError(t("payment.promoInvalid"));
      }
    } catch (e) {
      setPromoError(t("payment.promoInvalid"));
    } finally {
      setValidatingPromo(false);
    }
  };

  const handleRemovePromo = () => {
    setAppliedPromo(null);
    setPromoInput("");
    setPromoError("");
  };

  const handleCopyEmail = async () => {
    try {
      await navigator.clipboard.writeText(etransferInfo.email);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch (e) {}
  };

  const handlePay = () => {
    setStatus("processing");
    // 실제 서비스에서는 여기서 e-Transfer 입금 확인(이메일/은행 연동)을 처리합니다.
    setTimeout(async () => {
      const perChildAmount = Math.round((amount / children.length) * 100) / 100;
      const perChildDiscount = Math.round((discount / children.length) * 100) / 100;
      const promoPayload = appliedPromo ? { code: appliedPromo.code, discountAmount: perChildDiscount } : null;
      const ok = await onPaid(perChildAmount, method, promoPayload);
      setStatus(ok ? "done" : "error");
    }, 1400);
  };

  return (
    <div style={styles.sheetBackdrop} onClick={status === "idle" ? onClose : undefined}>
      <div style={styles.sheet} onClick={(e) => e.stopPropagation()} className="fade-item">
        <div style={styles.sheetHandle} />

        {status === "done" ? (
          <div style={{ textAlign: "center", padding: "24px 0 8px" }}>
            <div style={styles.successCircle}><Check size={26} color="#fff" /></div>
            <div style={{ fontSize: 17, fontWeight: 800, color: "#33402F", marginTop: 14 }}>{t("payment.doneTitle")}</div>
            <div style={{ fontSize: 13.5, color: "#7C8A7C", marginTop: 4 }}>
              {childNames} · {t("payment.doneMsg", { amount: formatCAD(amount) })}
            </div>
            <button onClick={onClose} style={{ ...styles.sheetBtn, background: "#4F7A44", color: "#fff", marginTop: 20 }}>
              {t("common.confirm")}
            </button>
          </div>
        ) : status === "error" ? (
          <div style={{ textAlign: "center", padding: "24px 0 8px" }}>
            <div style={{ ...styles.successCircle, background: "#C0392B" }}><X size={26} color="#fff" /></div>
            <div style={{ fontSize: 17, fontWeight: 800, color: "#33402F", marginTop: 14 }}>{t("payment.errorTitle")}</div>
            <div style={{ fontSize: 13.5, color: "#7C8A7C", marginTop: 4 }}>{t("payment.errorMsg")}</div>
            <button onClick={() => setStatus("idle")} style={{ ...styles.sheetBtn, background: "#4F7A44", color: "#fff", marginTop: 20 }}>
              {t("payment.retry")}
            </button>
          </div>
        ) : (
          <>
            <div style={styles.sheetHeader}>
              <div style={{ fontSize: 15, fontWeight: 700, color: "#33402F" }}>{t("payment.title")} · {childNames}</div>
              <button onClick={onClose} style={styles.iconBtn}><X size={18} /></button>
            </div>

            <div style={{ fontSize: 12.5, color: "#7C8A7C", fontWeight: 700, margin: "4px 2px 8px" }}>{t("payment.promoTitle")}</div>
            {appliedPromo ? (
              <div style={styles.promoAppliedRow}>
                <span style={{ fontWeight: 700, fontSize: 13, color: "#4F7A44" }}>✓ {appliedPromo.code}</span>
                <button onClick={handleRemovePromo} style={styles.promoRemoveBtn}>{t("common.delete")}</button>
              </div>
            ) : (
              <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: promoError ? 6 : 0 }}>
                <input
                  value={promoInput}
                  onChange={(e) => setPromoInput(e.target.value)}
                  placeholder={t("payment.promoPlaceholder")}
                  style={{ ...styles.input, flex: 1, minWidth: 0 }}
                  autoCapitalize="characters"
                />
                <button onClick={handleApplyPromo} disabled={validatingPromo || !promoInput.trim()} style={styles.promoApplyBtn}>
                  {validatingPromo ? <Loader2 size={14} className="spin" /> : t("payment.promoApply")}
                </button>
              </div>
            )}
            {promoError && <div style={{ fontSize: 12, color: "#C0392B", marginBottom: 8 }}>{promoError}</div>}

            <div style={styles.paySummary}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13.5, color: "#7C8A7C" }}>
                <span>{t("payment.monthlyFee")} ({formatCAD(MONTHLY_FEE)} × {fee.count})</span>
                <span>{formatCAD(fee.subtotal)}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13.5, color: "#7C8A7C", marginTop: 6 }}>
                <span>{t("payment.tax")}</span>
                <span>{formatCAD(fee.tax)}</span>
              </div>
              {discount > 0 && (
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 13.5, color: "#4F7A44", marginTop: 6 }}>
                  <span>{t("payment.promoDiscount")}</span>
                  <span>-{formatCAD(discount)}</span>
                </div>
              )}
              <div style={{ height: 1, background: "#EDF2ED", margin: "10px 0" }} />
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 16, fontWeight: 800, color: "#33402F" }}>
                <span>{t("payment.total")}</span>
                <span>{formatCAD(amount)}</span>
              </div>
            </div>

            <div style={{ fontSize: 12.5, color: "#7C8A7C", fontWeight: 700, margin: "18px 2px 8px" }}>{t("payment.methodTitle")}</div>
            <div style={styles.methodRowActive2}>
              <span style={{ fontSize: 16 }}>💸</span>
              <span style={{ fontWeight: 700, fontSize: 14 }}>Interac e-Transfer</span>
              <Check size={16} color="#4F7A44" style={{ marginLeft: "auto" }} />
            </div>

            <div style={styles.bankInfoCard}>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span style={{ fontSize: 12.5, color: "#7C8A7C" }}>{t("payment.recipient")}</span>
                <span style={{ fontSize: 13, fontWeight: 700, color: "#33402F" }}>{etransferInfo.recipient}</span>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 6 }}>
                <span style={{ fontSize: 12.5, color: "#7C8A7C" }}>{t("payment.email")}</span>
                <button onClick={handleCopyEmail} style={styles.copyBtn}>
                  {copied ? t("payment.copied") : `${etransferInfo.email} (${t("payment.copy")})`}
                </button>
              </div>
              {etransferInfo.securityAnswer && (
                <div style={{ display: "flex", justifyContent: "space-between", marginTop: 6 }}>
                  <span style={{ fontSize: 12.5, color: "#7C8A7C" }}>{t("payment.securityAnswer")}</span>
                  <span style={{ fontSize: 13, fontWeight: 700, color: "#33402F" }}>{etransferInfo.securityAnswer}</span>
                </div>
              )}
            </div>

            <button
              onClick={handlePay}
              disabled={status === "processing"}
              style={{
                ...styles.sheetBtn,
                marginTop: 20,
                background: "#4F7A44",
                color: "#fff",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: 8,
              }}
            >
              {status === "processing" ? (
                <><Loader2 size={16} className="spin" style={{ animation: "spin 0.8s linear infinite" }} /> {t("payment.processing")}</>
              ) : (
                t("payment.confirmBtn")
              )}
            </button>
            <div style={{ fontSize: 11, color: "#B4BDB4", textAlign: "center", marginTop: 10 }}>
              {t("payment.note")}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

