// 글자를 입력할 때마다 바로바로 서버에 저장하면(특히 네트워크가 느릴 때) 타이핑이 버벅여요.
// 그래서 화면엔 즉시 반영하되, 실제 저장은 "타이핑을 잠깐 멈췄을 때"(또는 다른 곳 클릭할 때)만 하도록 만든 입력창이에요.
function DebouncedInput({ value, onCommit, as = "input", delay = 500, ...props }) {
  const [local, setLocal] = useState(value ?? "");
  const timerRef = useRef(null);
  const lastCommittedRef = useRef(value ?? "");

  // 바깥에서(예: 다른 자리에서 저장 완료 후 새로고침되며) 값이 바뀌면 로컬 값도 맞춰줘요.
  useEffect(() => {
    if (value !== lastCommittedRef.current) {
      setLocal(value ?? "");
      lastCommittedRef.current = value ?? "";
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  const commit = (val) => {
    if (timerRef.current) clearTimeout(timerRef.current);
    lastCommittedRef.current = val;
    onCommit(val);
  };

  const handleChange = (e) => {
    const newVal = e.target.value;
    setLocal(newVal);
    if (timerRef.current) clearTimeout(timerRef.current);
    timerRef.current = setTimeout(() => commit(newVal), delay);
  };

  const handleBlur = () => commit(local);

  const Tag = as;
  return <Tag {...props} value={local} onChange={handleChange} onBlur={handleBlur} />;
}

function AdminMenuEditor({ menusByMonth, onUpdateMenus, onDeleteMenuMonth, onSendMenuNotification, activeYear, activeMonth }) {
  const [offset, setOffset] = useState(0); // 0=이번달, 1=다음달 (월별 보기에서만 사용)
  const [newDay, setNewDay] = useState("");
  const [combinedView, setCombinedView] = useState(false); // 12회 사이클이 월 중간에 걸칠 때, 이번달+다음달을 이어서 보는 모드
  const [allMenuMonths, setAllMenuMonths] = useState(null); // 지난 달 정리용 — 메뉴가 하나라도 있는 모든 달

  useEffect(() => {
    api.getMenuMonthKeys().then(setAllMenuMonths).catch(() => setAllMenuMonths([]));
  }, []);
  // "오늘 기준 이전 달"로만 제한하면, 아직 이번 달이 다 안 지나서도 정리하고 싶은 경우(예: 8월 남았지만 사이클은 이미 9월로 넘어간 경우)를
  // 놓치니까, 메뉴가 등록된 모든 달을 보여주고 관리자가 직접 골라서 지울 수 있게 해요.
  const allMenuMonthsList = allMenuMonths || [];

  const viewDate = new Date(activeYear, activeMonth - 1 + offset, 1);
  const viewYear = viewDate.getFullYear();
  const viewMonth = viewDate.getMonth() + 1;
  const viewKey = monthKey(viewYear, viewMonth);
  const menus = menusByMonth[viewKey] || {};
  const days = Object.keys(menus).map(Number).sort((a, b) => a - b);

  const nextDate = new Date(activeYear, activeMonth, 1);
  const nextYear = nextDate.getFullYear();
  const nextMonthNum = nextDate.getMonth() + 1;
  const nextKey = monthKey(nextYear, nextMonthNum);
  const nextMenus = menusByMonth[nextKey] || {};

  // 이어보기 모드는 "오늘 날짜 기준 이번 달"이 아니라, 이미 메뉴가 등록된 것 중 가장 최근 달을 기준으로 자동 계산해요.
  // (예: 9월 메뉴부터 미리 입력해뒀다면, 8+9월이 아니라 9+10월이 이어져야 하니까요.)
  const menuKeysWithData = Object.keys(menusByMonth).filter((k) => menusByMonth[k] && Object.keys(menusByMonth[k]).length > 0);
  const combinedBaseKey = menuKeysWithData.length > 0 ? menuKeysWithData.sort().slice(-1)[0] : monthKey(activeYear, activeMonth);
  const [combinedBaseYear, combinedBaseMonth] = combinedBaseKey.split("-").map(Number);
  const combinedNextDate = new Date(combinedBaseYear, combinedBaseMonth, 1);
  const combinedNextYear = combinedNextDate.getFullYear();
  const combinedNextMonthNum = combinedNextDate.getMonth() + 1;
  const combinedNextKey = monthKey(combinedNextYear, combinedNextMonthNum);
  const combinedBaseMenus = menusByMonth[combinedBaseKey] || {};
  const combinedNextMenus = menusByMonth[combinedNextKey] || {};

  // 이어보기 모드용 — (오늘 기준 이번달이 아니라) 메뉴가 등록된 마지막 달 + 그다음 달을 실제 날짜 순서로 하나로 합쳐요.
  const combinedEntries = combinedView
    ? [
        ...Object.keys(combinedBaseMenus).map(Number).sort((a, b) => a - b).map((d) => ({ year: combinedBaseYear, month: combinedBaseMonth, day: d, key: combinedBaseKey })),
        ...Object.keys(combinedNextMenus).map(Number).sort((a, b) => a - b).map((d) => ({ year: combinedNextYear, month: combinedNextMonthNum, day: d, key: combinedNextKey })),
      ]
    : [];

  function updateFieldFor(key, day, menusOfKey, fieldKey, value) {
    onUpdateMenus(key, { ...menusOfKey, [day]: { ...menusOfKey[day], [fieldKey]: value } });
  }
  const toggleHolidayFor = (key, day, menusOfKey) => {
    onUpdateMenus(key, { ...menusOfKey, [day]: { ...menusOfKey[day], isHoliday: !menusOfKey[day].isHoliday } });
  };
  const removeDayFor = (key, day, menusOfKey) => {
    const next = { ...menusOfKey };
    delete next[day];
    onUpdateMenus(key, next);
  };

  // 단일 월 보기용 (기존 방식 그대로)
  const updateField = (day, key, value) => updateFieldFor(viewKey, day, menus, key, value);
  const removeDay = (day) => removeDayFor(viewKey, day, menus);
  const toggleHoliday = (day) => toggleHolidayFor(viewKey, day, menus);

  const addDay = () => {
    const d = parseInt(newDay, 10);
    if (!d || d < 1 || d > 31 || menus[d]) return;
    onUpdateMenus(viewKey, { ...menus, [d]: { main: "", side: "", fruit: "", isHoliday: false, holidayLabel: "" } });
    setNewDay("");
  };

  // 이번달 메뉴를 다음달로 복사 — 다음달에 이미 등록된 날짜는 덮어쓰지 않고, 비어있는 날짜만 채워줍니다.
  const handleCopyToNextMonth = () => {
    onUpdateMenus(nextKey, { ...menus, ...nextMenus });
    setOffset(1);
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 6, flexWrap: "wrap", gap: 6 }}>
        <div style={styles.sectionTitle}>
          {combinedView ? `${monthLabel(combinedBaseYear, combinedBaseMonth)} ~ ${monthLabel(combinedNextYear, combinedNextMonthNum)} 메뉴 관리` : `${monthLabel(viewYear, viewMonth)} 메뉴 관리`}
        </div>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          <button
            onClick={() => setCombinedView((v) => !v)}
            style={{
              fontSize: 11.5,
              fontWeight: 700,
              padding: "6px 10px",
              borderRadius: 8,
              border: "1px solid #DCE3DC",
              background: combinedView ? "#4F7A44" : "#fff",
              color: combinedView ? "#fff" : "#5C6A5C",
              cursor: "pointer",
            }}
          >
            {combinedView ? "✓ 이어보기 중" : "이번달+다음달 이어보기"}
          </button>
          {!combinedView && (
            <div style={{ display: "flex", gap: 4 }}>
              <button onClick={() => setOffset((o) => Math.max(0, o - 1))} disabled={offset === 0} style={{ ...styles.iconBtn, opacity: offset === 0 ? 0.4 : 1 }}>
                <ChevronLeft size={16} />
              </button>
              <button onClick={() => setOffset((o) => Math.min(1, o + 1))} disabled={offset === 1} style={{ ...styles.iconBtn, opacity: offset === 1 ? 0.4 : 1 }}>
                <ChevronRight size={16} />
              </button>
            </div>
          )}
        </div>
      </div>
      <p style={styles.helperText}>
        {combinedView
          ? "12회 사이클이 월 중간에 걸칠 때 편하도록, 이번달과 다음달 배송일을 날짜 순서대로 이어서 보여줘요."
          : "여기서 수정하면 학부모 화면의 캘린더·배송일 메뉴에 바로 반영돼요. 다음 달 메뉴도 미리 준비해둘 수 있어요. 공휴일·방학처럼 배송이 없는 날은 \"공휴일/방학으로 등록\"을 눌러 안내 문구만 넣어주세요."}
      </p>

      {!combinedView && offset === 0 && days.length > 0 && (
        <button onClick={handleCopyToNextMonth} style={styles.copyMenuBtn}>
          이번달 메뉴를 다음달로 복사 (다음달에 이미 있는 날짜는 유지돼요)
        </button>
      )}

      {combinedView ? (
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {combinedEntries.map((entry, i) => {
            const entryMenus = entry.key === combinedBaseKey ? combinedBaseMenus : combinedNextMenus;
            const menu = entryMenus[entry.day];
            if (!menu) return null;
            const isHoliday = !!menu.isHoliday;
            const wd = getWeekday(entry.year, entry.month, entry.day);
            const prevEntry = combinedEntries[i - 1];
            const showMonthDivider = i === 0 || (prevEntry && prevEntry.month !== entry.month);
            return (
              <div key={`${entry.key}-${entry.day}`}>
                {showMonthDivider && (
                  <div style={{ fontSize: 12, fontWeight: 800, color: "#9AA39A", margin: "10px 2px 4px" }}>
                    ── {monthLabel(entry.year, entry.month)} ──
                  </div>
                )}
                <div style={{ ...styles.menuEditRow, alignItems: "flex-start" }} className="fade-item">
                  <div style={styles.menuDateCol}>
                    <div style={{ fontSize: 12, color: "#9AA39A" }}>{WEEKDAYS[wd]}</div>
                    <div style={{ fontSize: 20, fontWeight: 800, color: isHoliday ? "#C0392B" : "#4F7A44" }}>{entry.day}</div>
                  </div>
                  <div style={styles.menuEditTextCol}>
                    <button
                      onClick={() => toggleHolidayFor(entry.key, entry.day, entryMenus)}
                      style={{ ...styles.holidayToggleBtn, ...(isHoliday ? styles.holidayToggleBtnActive : {}) }}
                    >
                      {isHoliday ? "✓ 공휴일/방학으로 등록됨" : "공휴일/방학으로 등록"}
                    </button>
                    {isHoliday ? (
                      <DebouncedInput
                        style={{ ...styles.menuEditInput, marginTop: 6, borderColor: "#F2C9C2", color: "#C0392B" }}
                        value={menu.holidayLabel || ""}
                        onCommit={(v) => updateFieldFor(entry.key, entry.day, entryMenus, "holidayLabel", v)}
                        placeholder="예: HAPPY BC Day, 겨울방학"
                      />
                    ) : (
                      <>
                        <DebouncedInput
                          style={{ ...styles.menuEditInput, marginTop: 6 }}
                          value={menu.main}
                          onCommit={(v) => updateFieldFor(entry.key, entry.day, entryMenus, "main", v)}
                          placeholder="메인 메뉴"
                        />
                        <DebouncedInput
                          style={{ ...styles.menuEditInput, marginTop: 6 }}
                          value={menu.side}
                          onCommit={(v) => updateFieldFor(entry.key, entry.day, entryMenus, "side", v)}
                          placeholder="사이드 메뉴"
                        />
                        <DebouncedInput
                          style={{ ...styles.menuEditInput, marginTop: 6 }}
                          value={menu.fruit || ""}
                          onCommit={(v) => updateFieldFor(entry.key, entry.day, entryMenus, "fruit", v)}
                          placeholder="과일"
                        />
                      </>
                    )}
                  </div>
                  <button onClick={() => removeDayFor(entry.key, entry.day, entryMenus)} style={styles.removeChildBtn}>
                    <X size={14} />
                  </button>
                </div>
              </div>
            );
          })}
          {combinedEntries.length === 0 && (
            <div style={{ fontSize: 13, color: "#9AA39A", padding: "10px 2px" }}>등록된 배송일이 아직 없어요.</div>
          )}

          <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 4 }}>
            <AddDayRow label={`${monthLabel(combinedBaseYear, combinedBaseMonth)}에 날짜 추가`} onAdd={(d) => onUpdateMenus(combinedBaseKey, { ...combinedBaseMenus, [d]: { main: "", side: "", fruit: "", isHoliday: false, holidayLabel: "" } })} disabledDays={combinedBaseMenus} />
            <AddDayRow label={`${monthLabel(combinedNextYear, combinedNextMonthNum)}에 날짜 추가`} onAdd={(d) => onUpdateMenus(combinedNextKey, { ...combinedNextMenus, [d]: { main: "", side: "", fruit: "", isHoliday: false, holidayLabel: "" } })} disabledDays={combinedNextMenus} />
          </div>
        </div>
      ) : (
        <>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            {days.map((d) => {
              const wd = getWeekday(viewYear, viewMonth, d);
              const isHoliday = !!menus[d].isHoliday;
              return (
                <div key={d} style={{ ...styles.menuEditRow, alignItems: "flex-start" }} className="fade-item">
                  <div style={styles.menuDateCol}>
                    <div style={{ fontSize: 12, color: "#9AA39A" }}>{WEEKDAYS[wd]}</div>
                    <div style={{ fontSize: 20, fontWeight: 800, color: isHoliday ? "#C0392B" : "#4F7A44" }}>{d}</div>
                  </div>
                  <div style={styles.menuEditTextCol}>
                    <button onClick={() => toggleHoliday(d)} style={{ ...styles.holidayToggleBtn, ...(isHoliday ? styles.holidayToggleBtnActive : {}) }}>
                      {isHoliday ? "✓ 공휴일/방학으로 등록됨" : "공휴일/방학으로 등록"}
                    </button>
                    {isHoliday ? (
                      <DebouncedInput
                        style={{ ...styles.menuEditInput, marginTop: 6, borderColor: "#F2C9C2", color: "#C0392B" }}
                        value={menus[d].holidayLabel || ""}
                        onCommit={(v) => updateField(d, "holidayLabel", v)}
                        placeholder="예: HAPPY BC Day, 겨울방학"
                      />
                    ) : (
                      <>
                        <DebouncedInput
                          style={{ ...styles.menuEditInput, marginTop: 6 }}
                          value={menus[d].main}
                          onCommit={(v) => updateField(d, "main", v)}
                          placeholder="메인 메뉴"
                        />
                        <DebouncedInput
                          style={{ ...styles.menuEditInput, marginTop: 6 }}
                          value={menus[d].side}
                          onCommit={(v) => updateField(d, "side", v)}
                          placeholder="사이드 메뉴"
                        />
                        <DebouncedInput
                          style={{ ...styles.menuEditInput, marginTop: 6 }}
                          value={menus[d].fruit || ""}
                          onCommit={(v) => updateField(d, "fruit", v)}
                          placeholder="과일"
                        />
                      </>
                    )}
                  </div>
                  <button onClick={() => removeDay(d)} style={styles.removeChildBtn}>
                    <X size={14} />
                  </button>
                </div>
              );
            })}
          </div>

          <div style={styles.addMenuRow}>
            <input
              type="number"
              min="1"
              max="31"
              value={newDay}
              onChange={(e) => setNewDay(e.target.value)}
              placeholder="날짜 (예: 3)"
              style={{ ...styles.fieldInput, width: 100 }}
            />
            <button onClick={addDay} style={{ ...styles.addChildBtn, width: "auto", flex: 1, padding: "12px 16px" }}>+ 배송일 추가</button>
          </div>
        </>
      )}

      <SendNotificationButton notice={{ title: "메뉴판 업데이트" }} onSend={onSendMenuNotification} label="🍱 학부모에게 메뉴 업데이트 알림 보내기" />

      {allMenuMonthsList.length > 0 && (
        <div style={{ marginTop: 24 }}>
          <div style={{ ...styles.sectionTitle, color: "#9AA39A" }}>메뉴판 정리 (등록된 모든 달)</div>
          <p style={styles.helperText}>더 이상 안 쓰는 달의 메뉴판을 골라서 지울 수 있어요. 지금 편집 중인 달도 목록에 보일 수 있으니, 지울 달을 잘 확인하고 눌러주세요.</p>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {allMenuMonthsList.map((key) => {
              const [y, m] = key.split("-").map(Number);
              return <DeleteMonthButton key={key} label={monthLabel(y, m)} monthKeyStr={key} onDelete={async () => { await onDeleteMenuMonth(key); setAllMenuMonths((prev) => prev.filter((k) => k !== key)); }} />;
            })}
          </div>
        </div>
      )}
    </div>
  );
}

// 지난 달 메뉴 하나를 통째로 지우는 버튼이에요. 되돌릴 수 없어서 두 번 눌러야 확정돼요.
function DeleteMonthButton({ label, onDelete }) {
  const [armed, setArmed] = useState(false);
  const [status, setStatus] = useState("idle"); // idle | working | error

  const handleClick = async () => {
    if (!armed) {
      setArmed(true);
      setTimeout(() => setArmed(false), 4000);
      return;
    }
    setStatus("working");
    try {
      await onDelete();
    } catch (e) {
      setStatus("error");
      setTimeout(() => setStatus("idle"), 2500);
      setArmed(false);
      return;
    }
    setStatus("idle");
    setArmed(false);
  };

  return (
    <button
      onClick={handleClick}
      disabled={status === "working"}
      style={{
        ...styles.revokeBtn,
        width: "100%",
        color: armed ? "#fff" : undefined,
        background: armed ? "#C0392B" : undefined,
      }}
    >
      {status === "working" ? "삭제 중..." : status === "error" ? "삭제 실패 ✕" : armed ? `정말로 ${label} 메뉴를 전부 지울까요? 다시 눌러 확정` : `${label} 메뉴 삭제`}
    </button>
  );
}

// 이어보기 모드에서 특정 달에 새 날짜를 추가하는 작은 입력줄이에요.
function AddDayRow({ label, onAdd, disabledDays }) {
  const [value, setValue] = useState("");
  const handleAdd = () => {
    const d = parseInt(value, 10);
    if (!d || d < 1 || d > 31 || disabledDays[d]) return;
    onAdd(d);
    setValue("");
  };
  return (
    <div style={styles.addMenuRow}>
      <input
        type="number"
        min="1"
        max="31"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder="날짜 (예: 3)"
        style={{ ...styles.fieldInput, width: 100 }}
      />
      <button onClick={handleAdd} style={{ ...styles.addChildBtn, width: "auto", flex: 1, padding: "12px 16px" }}>+ {label}</button>
    </div>
  );
}

function NoticeView({ notices, t }) {
  return (
    <div>
      <div style={styles.sectionTitle}>{t("notice.title")}</div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {notices.map((n) => (
          <div key={n.id} style={styles.noticeCard} className="fade-item">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div style={{ fontSize: 13, color: "#4F7A44", fontWeight: 700 }}>{n.date}</div>
            </div>
            <div style={{ fontSize: 15, fontWeight: 700, color: "#33402F", marginTop: 4 }}>{n.title}</div>
            <div style={{ fontSize: 13.5, color: "#5C6A5C", marginTop: 6, lineHeight: 1.5 }}>{n.body}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function todayLabel() {
  const now = new Date();
  return `${String(now.getMonth() + 1).padStart(2, "0")}.${String(now.getDate()).padStart(2, "0")}`;
}

function AdminNoticeEditor({ notices, onUpdateNotices, onSendNoticeNotification }) {
  const updateField = (id, key, value) => {
    onUpdateNotices(notices.map((n) => (n.id === id ? { ...n, [key]: value } : n)));
  };

  const removeNotice = (id) => {
    onUpdateNotices(notices.filter((n) => n.id !== id));
  };

  const addNotice = () => {
    onUpdateNotices([{ id: crypto.randomUUID(), date: todayLabel(), title: "", body: "" }, ...notices]);
  };

  return (
    <div>
      <div style={styles.sectionTitle}>공지사항 관리</div>
      <p style={styles.helperText}>여기서 작성·수정·삭제하면 학부모 화면의 공지사항에 바로 반영돼요. 다 작성한 뒤 "알림 보내기"를 누르면 학부모들에게 푸시 알림이 가요.</p>

      <button onClick={addNotice} style={{ ...styles.addChildBtn, marginBottom: 12 }}>+ 공지사항 추가</button>

      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {notices.map((n) => (
          <div key={n.id} style={styles.noticeEditCard} className="fade-item">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
              <DebouncedInput
                value={n.date}
                onCommit={(v) => updateField(n.id, "date", v)}
                style={{ ...styles.menuEditInput, width: 90, fontWeight: 700, color: "#4F7A44" }}
                placeholder="07.14"
              />
              <button onClick={() => removeNotice(n.id)} style={styles.removeChildBtn}>
                <X size={14} /> 삭제
              </button>
            </div>
            <DebouncedInput
              value={n.title}
              onCommit={(v) => updateField(n.id, "title", v)}
              style={styles.menuEditInput}
              placeholder="공지 제목"
            />
            <DebouncedInput
              as="textarea"
              value={n.body}
              onCommit={(v) => updateField(n.id, "body", v)}
              style={{ ...styles.menuEditInput, marginTop: 6, height: 72, resize: "none", paddingTop: 10 }}
              placeholder="공지 내용"
            />
            <SendNotificationButton notice={n} onSend={onSendNoticeNotification} />
          </div>
        ))}
      </div>
    </div>
  );
}

// 공지사항 하나를 학부모들에게 푸시 알림으로 보내는 버튼이에요. 발송 중/발송완료 상태를 따로 관리해요.
function SendNotificationButton({ notice, onSend, label }) {
  const [status, setStatus] = useState("idle"); // idle | sending | sent | error

  const handleClick = async () => {
    if (!notice.title.trim()) return;
    setStatus("sending");
    try {
      await onSend(notice);
      setStatus("sent");
      setTimeout(() => setStatus("idle"), 2500);
    } catch (e) {
      setStatus("error");
      setTimeout(() => setStatus("idle"), 2500);
    }
  };

  return (
    <button
      onClick={handleClick}
      disabled={status === "sending" || !notice.title.trim()}
      style={{ ...styles.sendNotificationBtn, marginTop: 8, opacity: !notice.title.trim() ? 0.5 : 1 }}
    >
      {status === "sending" ? "발송 중..." : status === "sent" ? "✓ 알림을 보냈어요" : status === "error" ? "발송 실패, 다시 시도해주세요" : (label || "📢 학부모에게 알림 보내기")}
    </button>
  );
}

